INSERT INTO `bltt_chatbot_responses` (`chatbot_responses_id`, `chatbot_responses`, `intent_tt_group_name`, `created_datetime`, `updated_datetime`) VALUES
(1, 'Điều 1. Phạm vi điều chỉnh\nBộ luật tố tụng hình sự quy định trình tự, thủ tục tiếp nhận, giải quyết nguồn tin về tội phạm, khởi tố, điều tra, truy tố, xét xử và một số thủ tục thi hành án hình sự; nhiệm vụ, quyền hạn và mối quan hệ giữa các cơ quan có thẩm quyền tiến hành tố tụng; nhiệm vụ, quyền hạn và trách nhiệm của người có thẩm quyền tiến hành tố tụng; quyền và nghĩa vụ của người tham gia tố tụng, cơ quan, tổ chức, cá nhân; hợp tác quốc tế trong tố tụng hình sự.', 'tt1', '2024-05-01 01:06:25', '2024-05-02 19:20:43'),
(2, 'Điều 2. Nhiệm vụ của Bộ luật tố tụng hình sự\r\nBộ luật tố tụng hình sự có nhiệm vụ bảo đảm phát hiện chính xác và xử lý công minh, kịp thời mọi hành vi phạm tội, phòng ngừa, ngăn chặn tội phạm, không để lọt tội phạm, không làm oan người vô tội; góp phần bảo vệ công lý, bảo vệ quyền con người, quyền công dân, bảo vệ chế độ xã hội chủ nghĩa, bảo vệ lợi ích của Nhà nước, quyền và lợi ích hợp pháp của tổ chức, cá nhân, giáo dục mọi người ý thức tuân theo pháp luật, đấu tranh phòng ngừa và chống tội phạm.', 'tt2', '2024-05-02 19:21:20', '2024-05-02 19:21:27'),
(3, 'Điều 3. Hiệu lực của Bộ luật tố tụng hình sự\r\n1. Bộ luật tố tụng hình sự có hiệu lực đối với mọi hoạt động tố tụng hình sự trên lãnh thổ nước Cộng hòa xã hội chủ nghĩa Việt Nam.\r\n2. Hoạt động tố tụng hình sự đối với người nước ngoài phạm tội trên lãnh thổ nước Cộng hòa xã hội chủ nghĩa Việt Nam được tiến hành theo quy định của điều ước quốc tế mà Cộng hòa xã hội chủ nghĩa Việt Nam là thành viên hoặc theo nguyên tắc có đi có lại.\r\nTrường hợp người nước ngoài thuộc đối tượng được hưởng quyền miễn trừ ngoại giao hoặc lãnh sự theo pháp luật Việt Nam, điều ước quốc tế mà Cộng hoà xã hội chủ nghĩa Việt Nam là thành viên hoặc tập quán quốc tế thì được giải quyết theo quy định của điều ước quốc tế hoặc tập quán quốc tế đó; trường hợp điều ước quốc tế đó không quy định hoặc không có tập quán quốc tế thì được giải quyết bằng con đường ngoại giao.', 'tt3', '2024-05-02 19:26:03', '2024-05-02 19:26:03'),
(4, 'Điều 4. Giải thích từ ngữ\r\n1. Trong Bộ luật này, các từ ngữ dưới đây được hiểu như sau:\r\na) Cơ quan có thẩm quyền tiến hành tố tụng gồm cơ quan tiến hành tố tụng và cơ quan được giao nhiệm vụ tiến hành một số hoạt động điều tra.\r\nb) Người có thẩm quyền tiến hành tố tụng gồm người tiến hành tố tụng và người được giao nhiệm vụ tiến hành một số hoạt động điều tra.\r\nc) Người tham gia tố tụng là cá nhân, cơ quan, tổ chức tham gia hoạt động tố tụng theo quy định của Bộ luật này.\r\nd) Nguồn tin về tội phạm gồm tố giác, tin báo về tội phạm, kiến nghị khởi tố của cơ quan, tổ chức, cá nhân, lời khai của người phạm tội tự thú và thông tin về tội phạm do cơ quan có thẩm quyền tiến hành tố tụng trực tiếp phát hiện.\r\nđ) Người bị buộc tội gồm người bị bắt, người bị tạm giữ, bị can, bị cáo.\r\ne) Người thân thích của người tham gia tố tụng, người có thẩm quyền tiến hành tố tụng là người có quan hệ với người tham gia tố tụng, người có thẩm quyền tiến hành tố tụng gồm vợ, chồng, bố đẻ, mẹ đẻ, bố chồng, mẹ chồng, bố vợ, mẹ vợ, bố nuôi, mẹ nuôi, con đẻ, con nuôi; ông nội, bà nội, ông ngoại, bà ngoại, anh ruột, chị ruột, em ruột; cụ nội, cụ ngoại, bác ruột, chú ruột, cậu ruột, cô ruột, dì ruột, cháu ruột.\r\ng) Đương sự gồm nguyên đơn dân sự, bị đơn dân sự, người có quyền lợi, nghĩa vụ liên quan đến vụ án hình sự.\r\nh) Tự thú là việc người phạm tội tự nguyện khai báo với cơ quan, tổ chức về hành vi phạm tội của mình trước khi tội phạm hoặc người phạm tội bị phát hiện.\r\ni) Đầu thú là việc người phạm tội sau khi bị phát hiện đã tự nguyện ra trình diện và khai báo với cơ quan có thẩm quyền về hành vi phạm tội của mình.\r\nk) Áp giải là việc cơ quan có thẩm quyền cưỡng chế người bị giữ trong trường hợp khẩn cấp, bị bắt, bị tạm giữ, bị can, bị cáo đến địa điểm tiến hành điều tra, truy tố hoặc xét xử.\r\nl) Dẫn giải là việc cơ quan có thẩm quyền cưỡng chế người làm chứng, người bị tố giác hoặc bị kiến nghị khởi tố đến địa điểm tiến hành điều tra, truy tố, xét xử hoặc người bị hại từ chối giám định.\r\nm) Danh bản là bản ghi thông tin tóm tắt về lý lịch, nhân dạng, ảnh chụp ba tư thế, in dấu vân hai ngón tay trỏ của bị can do cơ quan có thẩm quyền lập và lưu giữ.\r\nn) Chỉ bản là bản ghi thông tin tóm tắt về lý lịch và in dấu vân tất cả các ngón tay của bị can do cơ quan có thẩm quyền lập và lưu giữ.\r\no) Vi phạm nghiêm trọng thủ tục tố tụng là việc cơ quan, người có thẩm quyền tiến hành tố tụng trong quá trình khởi tố, điều tra, truy tố, xét xử không thực hiện hoặc thực hiện không đúng, không đầy đủ các trình tự, thủ tục do Bộ luật này quy định và đã xâm hại nghiêm trọng đến quyền, lợi ích hợp pháp của người tham gia tố tụng hoặc làm ảnh hưởng đến việc xác định sự thật khách quan, toàn diện của vụ án.\r\n2. Trong Bộ luật này, những từ ngữ dưới đây được gọi như sau:\r\na) Cơ quan điều tra Công an huyện, quận, thị xã, thành phố thuộc tỉnh, thành phố thuộc thành phố trực thuộc trung ương sau đây gọi là Cơ quan điều tra cấp huyện.\r\nb) Cơ quan điều tra Công an tỉnh, thành phố trực thuộc trung ương sau đây gọi là Cơ quan điều tra cấp tỉnh.\r\nc) Cơ quan điều tra quân sự quân khu và tương đương sau đây gọi là Cơ quan điều tra quân sự cấp quân khu.\r\nd) Viện kiểm sát nhân dân huyện, quận, thị xã, thành phố thuộc tỉnh, thành phố thuộc thành phố trực thuộc trung ương sau đây gọi là Viện kiểm sát nhân dân cấp huyện.\r\nđ) Viện kiểm sát nhân dân tỉnh, thành phố trực thuộc trung ương sau đây gọi là Viện kiểm sát nhân dân cấp tỉnh.\r\ne) Viện kiểm sát quân sự quân khu và tương đương sau đây gọi là Viện kiểm sát quân sự cấp quân khu.\r\ng) Tòa án nhân dân huyện, quận, thị xã, thành phố thuộc tỉnh, thành phố thuộc thành phố trực thuộc trung ương sau đây gọi là Tòa án nhân dân cấp huyện.\r\nh) Tòa án nhân dân tỉnh, thành phố trực thuộc trung ương sau đây gọi là Tòa án nhân dân cấp tỉnh.\r\ni) Tòa án quân sự quân khu và tương đương sau đây gọi là Tòa án quân sự cấp quân khu.', 'tt4', '2024-05-02 19:26:03', '2024-05-02 19:26:03'),
(5, 'Điều 5. Trách nhiệm của cơ quan nhà nước, tổ chức và cá nhân trong đấu tranh phòng, chống tội phạm\r\n1. Trong phạm vi trách nhiệm của mình, cơ quan nhà nước phải áp dụng các biện pháp phòng ngừa tội phạm, phối hợp với cơ quan có thẩm quyền tiến hành tố tụng trong việc đấu tranh phòng, chống tội phạm.\r\nCơ quan nhà nước phải thường xuyên kiểm tra, thanh tra việc thực hiện chức năng, nhiệm vụ được giao; phát hiện kịp thời hành vi vi phạm pháp luật để xử lý và thông báo ngay cho Cơ quan điều tra, Viện kiểm sát mọi hành vi phạm tội xảy ra trong cơ quan và trong lĩnh vực quản lý của mình; kiến nghị và gửi tài liệu có liên quan cho Cơ quan điều tra, Viện kiểm sát xem xét, khởi tố đối với người thực hiện hành vi phạm tội.\r\nThủ trưởng cơ quan nhà nước phải chịu trách nhiệm về việc không thông báo hoặc cung cấp thông tin sai sự thật về hành vi phạm tội xảy ra trong cơ quan và trong lĩnh vực quản lý của mình cho Cơ quan điều tra, Viện kiểm sát.\r\n2. Tổ chức, cá nhân có quyền và nghĩa vụ phát hiện, tố giác, báo tin về tội phạm; tham gia đấu tranh phòng, chống tội phạm.\r\n3. Cơ quan có thẩm quyền tiến hành tố tụng có trách nhiệm tạo điều kiện để cơ quan nhà nước, tổ chức và cá nhân tham gia đấu tranh phòng, chống tội phạm.\r\n4. Cơ quan nhà nước, tổ chức và cá nhân có trách nhiệm thực hiện yêu cầu và tạo điều kiện để cơ quan, người có thẩm quyền tiến hành tố tụng thực hiện nhiệm vụ.\r\n5. Cơ quan thanh tra, kiểm toán nhà nước có trách nhiệm phối hợp với cơ quan có thẩm quyền tiến hành tố tụng trong việc phát hiện và xử lý tội phạm. Khi phát hiện vụ việc có dấu hiệu tội phạm thì phải chuyển ngay các tài liệu, đồ vật có liên quan và kiến nghị Cơ quan điều tra, Viện kiểm sát xem xét, khởi tố vụ án hình sự.\r\n6. Nghiêm cấm mọi hành vi cản trở hoạt động của cơ quan, người có thẩm quyền tiến hành tố tụng thực hiện nhiệm vụ.', 'tt5', '2024-05-02 19:26:03', '2024-05-02 19:26:03'),
(6, 'Điều 6. Phát hiện và khắc phục nguyên nhân, điều kiện phạm tội\r\n1. Trong quá trình tiến hành tố tụng hình sự, cơ quan có thẩm quyền tiến hành tố tụng có trách nhiệm phát hiện nguyên nhân và điều kiện phạm tội, yêu cầu, kiến nghị cơ quan, tổ chức hữu quan áp dụng các biện pháp khắc phục và phòng ngừa.\r\n2. Cơ quan, tổ chức hữu quan phải thực hiện yêu cầu, kiến nghị của cơ quan có thẩm quyền tiến hành tố tụng. Trong thời hạn 15 ngày kể từ ngày nhận được yêu cầu, kiến nghị, cơ quan, tổ chức hữu quan phải trả lời bằng văn bản về việc thực hiện yêu cầu, kiến nghị của cơ quan có thẩm quyền tiến hành tố tụng.', 'tt6', '2024-05-02 19:26:03', '2024-05-02 19:26:03'),
(7, 'Điều 7. Bảo đảm pháp chế xã hội chủ nghĩa trong tố tụng hình sự\r\nMọi hoạt động tố tụng hình sự phải được thực hiện theo quy định của Bộ luật này. Không được giải quyết nguồn tin về tội phạm, khởi tố, điều tra, truy tố, xét xử ngoài những căn cứ và trình tự, thủ tục do Bộ luật này quy định.', 'tt7', '2024-05-02 19:26:03', '2024-05-02 19:26:03'),
(8, 'Điều 8. Tôn trọng và bảo vệ quyền con người, quyền và lợi ích hợp pháp của cá nhân\r\nKhi tiến hành tố tụng, trong phạm vi nhiệm vụ, quyền hạn của mình, cơ quan, người có thẩm quyền tiến hành tố tụng phải tôn trọng và bảo vệ quyền con người, quyền và lợi ích hợp pháp của cá nhân; thường xuyên kiểm tra tính hợp pháp và sự cần thiết của những biện pháp đã áp dụng, kịp thời hủy bỏ hoặc thay đổi những biện pháp đó nếu xét thấy có vi phạm pháp luật hoặc không còn cần thiết.', 'tt8', '2024-05-02 19:26:03', '2024-05-02 19:26:03'),
(9, 'Điều 9. Bảo đảm quyền bình đẳng trước pháp luật\r\nTố tụng hình sự được tiến hành theo nguyên tắc mọi người đều bình đẳng trước pháp luật, không phân biệt dân tộc, giới tính, tín ngưỡng, tôn giáo, thành phần và địa vị xã hội. Bất cứ người nào phạm tội đều bị xử lý theo pháp luật.\r\nMọi pháp nhân đều bình đẳng trước pháp luật, không phân biệt hình thức sở hữu và thành phần kinh tế.', 'tt9', '2024-05-02 19:26:03', '2024-05-02 19:26:03'),
(10, 'Điều 10. Bảo đảm quyền bất khả xâm phạm về thân thể\r\nMọi người có quyền bất khả xâm phạm về thân thể. Không ai bị bắt nếu không có quyết định của Tòa án, quyết định hoặc phê chuẩn của Viện kiểm sát, trừ trường hợp phạm tội quả tang.\r\nViệc giữ người trong trường hợp khẩn cấp, việc bắt, tạm giữ, tạm giam người phải theo quy định của Bộ luật này. Nghiêm cấm tra tấn, bức cung, dùng nhục hình hay bất kỳ hình thức đối xử nào khác xâm phạm thân thể, tính mạng, sức khỏe của con người.', 'tt10', '2024-05-02 19:26:03', '2024-05-02 19:26:03'),
(11, 'Điều 11. Bảo hộ tính mạng, sức khoẻ, danh dự, nhân phẩm, tài sản của cá nhân; danh dự, uy tín, tài sản của pháp nhân\r\nMọi người có quyền được pháp luật bảo hộ về tính mạng, sức khoẻ, danh dự, nhân phẩm, tài sản.\r\nMọi hành vi xâm phạm trái pháp luật tính mạng, sức khoẻ, danh dự, nhân phẩm, tài sản của cá nhân; xâm phạm danh dự, uy tín, tài sản của pháp nhân đều bị xử lý theo pháp luật.\r\nCông dân Việt Nam không thể bị trục xuất, giao nộp cho nhà nước khác.', 'tt11', '2024-05-02 19:26:03', '2024-05-02 19:26:03'),
(12, 'Điều 12. Bảo đảm quyền bất khả xâm phạm về chỗ ở, đời sống riêng tư, bí mật cá nhân, bí mật gia đình, an toàn và bí mật thư tín, điện thoại, điện tín của cá nhân\r\nKhông ai được xâm phạm trái pháp luật chỗ ở, đời sống riêng tư, bí mật cá nhân, bí mật gia đình, an toàn và bí mật thư tín, điện thoại, điện tín và các hình thức trao đổi thông tin riêng tư khác của cá nhân.\r\nViệc khám xét chỗ ở; khám xét, tạm giữ và thu giữ thư tín, điện thoại, điện tín, dữ liệu điện tử và các hình thức trao đổi thông tin riêng tư khác phải được thực hiện theo quy định của Bộ luật này.', 'tt12', '2024-05-02 19:26:03', '2024-05-02 19:26:03'),
(13, 'Điều 13. Suy đoán vô tội\r\nNgười bị buộc tội được coi là không có tội cho đến khi được chứng minh theo trình tự, thủ tục do Bộ luật này quy định và có bản án kết tội của Tòa án đã có hiệu lực pháp luật.\r\nKhi không đủ và không thể làm sáng tỏ căn cứ để buộc tội, kết tội theo trình tự, thủ tục do Bộ luật này quy định thì cơ quan, người có thẩm quyền tiến hành tố tụng phải kết luận người bị buộc tội không có tội.', 'tt13', '2024-05-02 22:35:13', '2024-05-02 22:35:13'),
(14, 'Điều 14. Không ai bị kết án hai lần vì một tội phạm\r\nKhông được khởi tố, điều tra, truy tố, xét xử đối với người mà hành vi của họ đã có bản án của Tòa án đã có hiệu lực pháp luật, trừ trường hợp họ thực hiện hành vi nguy hiểm khác cho xã hội mà Bộ luật hình sự quy định là tội phạm.', 'tt14', '2024-05-02 22:40:28', '2024-05-02 22:40:28'),
(15, 'Điều 15. Xác định sự thật của vụ án\r\nTrách nhiệm chứng minh tội phạm thuộc về cơ quan có thẩm quyền tiến hành tố tụng. Người bị buộc tội có quyền nhưng không buộc phải chứng minh là mình vô tội.\r\nTrong phạm vi nhiệm vụ, quyền hạn của mình, cơ quan có thẩm quyền tiến hành tố tụng phải áp dụng các biện pháp hợp pháp để xác định sự thật của vụ án một cách khách quan, toàn diện và đầy đủ, làm rõ chứng cứ xác định có tội và chứng cứ xác định vô tội, tình tiết tăng nặng và tình tiết giảm nhẹ trách nhiệm hình sự của người bị buộc tội.', 'tt15', '2024-05-02 22:40:28', '2024-05-02 22:40:28'),
(16, 'Điều 16. Bảo đảm quyền bào chữa của người bị buộc tội, bảo vệ quyền và lợi ích hợp pháp của bị hại, đương sự\r\nNgười bị buộc tội có quyền tự bào chữa, nhờ luật sư hoặc người khác bào chữa.\r\nCơ quan, người có thẩm quyền tiến hành tố tụng có trách nhiệm thông báo, giải thích và bảo đảm cho người bị buộc tội, bị hại, đương sự thực hiện đầy đủ quyền bào chữa, quyền và lợi ích hợp pháp của họ theo quy định của Bộ luật này.', 'tt16', '2024-05-02 22:40:28', '2024-05-02 22:40:28'),
(17, 'Điều 17. Trách nhiệm của cơ quan, người có thẩm quyền tiến hành tố tụng\r\nTrong quá trình tiến hành tố tụng, cơ quan, người có thẩm quyền tiến hành tố tụng phải nghiêm chỉnh thực hiện quy định của pháp luật và phải chịu trách nhiệm về hành vi, quyết định của mình.\r\nNgười vi phạm pháp luật trong việc giữ người trong trường hợp khẩn cấp, bắt, giam, giữ, khởi tố, điều tra, truy tố, xét xử, thi hành án thì tuỳ tính chất, mức độ vi phạm mà bị xử lý kỷ luật hoặc bị truy cứu trách nhiệm hình sự theo quy định của luật.', 'tt17', '2024-05-02 22:40:28', '2024-05-02 22:40:28'),
(18, 'Điều 18. Trách nhiệm khởi tố và xử lý vụ án hình sự\r\nKhi phát hiện hành vi có dấu hiệu tội phạm, trong phạm vi nhiệm vụ, quyền hạn của mình, cơ quan có thẩm quyền tiến hành tố tụng có trách nhiệm khởi tố vụ án, áp dụng các biện pháp do Bộ luật này quy định để xác định tội phạm và xử lý người phạm tội, pháp nhân phạm tội.\r\nKhông được khởi tố vụ án ngoài những căn cứ và trình tự, thủ tục do Bộ luật này quy định.', 'tt18', '2024-05-02 22:40:28', '2024-05-02 22:40:28'),
(19, 'Điều 19. Tuân thủ pháp luật trong hoạt động điều tra\r\nCơ quan điều tra, cơ quan được giao nhiệm vụ tiến hành một số hoạt động điều tra phải tuân thủ pháp luật khi tiến hành hoạt động điều tra theo quy định của Bộ luật này.\r\nMọi hoạt động điều tra phải tôn trọng sự thật, tiến hành khách quan, toàn diện và đầy đủ; phát hiện nhanh chóng, chính xác mọi hành vi phạm tội, làm rõ chứng cứ xác định có tội và chứng cứ xác định vô tội, tình tiết tăng nặng, tình tiết giảm nhẹ trách nhiệm hình sự, nguyên nhân, điều kiện phạm tội và những tình tiết khác có ý nghĩa đối với việc giải quyết vụ án.', 'tt19', '2024-05-02 22:40:28', '2024-05-02 22:40:28'),
(20, 'Điều 20. Trách nhiệm thực hành quyền công tố và kiểm sát việc tuân theo pháp luật trong tố tụng hình sự\r\nViện kiểm sát thực hành quyền công tố và kiểm sát việc tuân theo pháp luật trong tố tụng hình sự, quyết định việc buộc tội, phát hiện vi phạm pháp luật nhằm bảo đảm mọi hành vi phạm tội, người phạm tội, pháp nhân phạm tội, vi phạm pháp luật đều phải được phát hiện và xử lý kịp thời, nghiêm minh, việc khởi tố, điều tra, truy tố, xét xử, thi hành án đúng người, đúng tội, đúng pháp luật, không để lọt tội phạm và người phạm tội, pháp nhân phạm tội, không làm oan người vô tội.', 'tt20', '2024-05-02 22:40:28', '2024-05-02 22:40:28'),
(21, 'Điều 21. Bảo đảm sự vô tư của người có thẩm quyền tiến hành tố tụng, người tham gia tố tụng\r\nNgười có thẩm quyền tiến hành tố tụng, người phiên dịch, người dịch thuật, người giám định, người định giá tài sản, người chứng kiến không được tham gia tố tụng nếu có lý do cho rằng họ có thể không vô tư trong khi thực hiện nhiệm vụ.', 'tt21', '2024-05-02 22:40:28', '2024-05-02 22:40:28'),
(22, 'Điều 22. Thực hiện chế độ xét xử có Hội thẩm tham gia\r\nViệc xét xử sơ thẩm của Tòa án có Hội thẩm tham gia, trừ trường hợp xét xử theo thủ tục rút gọn do Bộ luật này quy định.', 'tt22', '2024-05-02 22:40:28', '2024-05-02 22:40:28'),
(23, 'Điều 23. Thẩm phán, Hội thẩm xét xử độc lập và chỉ tuân theo pháp luật\r\nThẩm phán, Hội thẩm xét xử độc lập và chỉ tuân theo pháp luật; nghiêm cấm cơ quan, tổ chức, cá nhân can thiệp vào việc xét xử của Thẩm phán, Hội thẩm.\r\nCơ quan, tổ chức, cá nhân can thiệp vào việc xét xử của Thẩm phán, Hội thẩm dưới bất kỳ hình thức nào thì tùy tính chất, mức độ vi phạm mà bị xử lý kỷ luật, xử phạt vi phạm hành chính hoặc bị truy cứu trách nhiệm hình sự theo quy định của luật.', 'tt23', '2024-05-02 22:40:28', '2024-05-02 22:40:28'),
(24, 'Điều 24. Tòa án xét xử tập thể\r\nTòa án xét xử tập thể và quyết định theo đa số, trừ trường hợp xét xử theo thủ tục rút gọn do Bộ luật này quy định.', 'tt24', '2024-05-02 22:40:28', '2024-05-02 22:40:28'),
(25, 'Điều 25. Tòa án xét xử kịp thời, công bằng, công khai\r\nTòa án xét xử kịp thời trong thời hạn luật định, bảo đảm công bằng.\r\nTòa án xét xử công khai, mọi người đều có quyền tham dự phiên tòa, trừ trường hợp do Bộ luật này quy định. Trường hợp đặc biệt cần giữ bí mật nhà nước, thuần phong, mỹ tục của dân tộc, bảo vệ người dưới 18 tuổi hoặc để giữ bí mật đời tư theo yêu cầu chính đáng của đương sự thì Tòa án có thể xét xử kín nhưng phải tuyên án công khai.', 'tt25', '2024-05-02 22:40:28', '2024-05-02 22:40:28'),
(26, 'Điều 26. Tranh tụng trong xét xử được bảo đảm\r\nTrong quá trình khởi tố, điều tra, truy tố, xét xử, Điều tra viên, Kiểm sát viên, người khác có thẩm quyền tiến hành tố tụng, người bị buộc tội, người bào chữa và người tham gia tố tụng khác đều có quyền bình đẳng trong việc đưa ra chứng cứ, đánh giá chứng cứ, đưa ra yêu cầu để làm rõ sự thật khách quan của vụ án.\r\nTài liệu, chứng cứ trong hồ sơ vụ án do Viện kiểm sát chuyển đến Tòa án để xét xử phải đầy đủ và hợp pháp. Phiên tòa xét xử vụ án hình sự phải có mặt đầy đủ những người theo quy định của Bộ luật này, trường hợp vắng mặt phải vì lý do bất khả kháng hoặc do trở ngại khách quan hoặc trường hợp khác do Bộ luật này quy định. Tòa án có trách nhiệm tạo điều kiện cho Kiểm sát viên, bị cáo, người bào chữa, những người tham gia tố tụng khác thực hiện đầy đủ quyền, nghĩa vụ của mình và tranh tụng dân chủ, bình đẳng trước Tòa án.\r\nMọi chứng cứ xác định có tội, chứng cứ xác định vô tội, tình tiết tăng nặng, tình tiết giảm nhẹ trách nhiệm hình sự, áp dụng điểm, khoản, điều của Bộ luật hình sự để xác định tội danh, quyết định hình phạt, mức bồi thường thiệt hại đối với bị cáo, xử lý vật chứng và những tình tiết khác có ý nghĩa giải quyết vụ án đều phải được trình bày, tranh luận, làm rõ tại phiên tòa.\r\nBản án, quyết định của Tòa án phải căn cứ vào kết quả kiểm tra, đánh giá chứng cứ và kết quả tranh tụng tại phiên tòa.', 'tt26', '2024-05-02 22:40:28', '2024-05-02 22:40:28'),
(27, 'Điều 27. Chế độ xét xử sơ thẩm, phúc thẩm được bảo đảm\r\n1. Chế độ xét xử sơ thẩm, phúc thẩm được bảo đảm.\r\nBản án, quyết định sơ thẩm của Tòa án có thể bị kháng cáo, kháng nghị theo quy định của Bộ luật này. Bản án, quyết định sơ thẩm không bị kháng cáo, kháng nghị trong thời hạn do Bộ luật này quy định thì có hiệu lực pháp luật.\r\nBản án, quyết định sơ thẩm bị kháng cáo, kháng nghị thì vụ án phải được xét xử phúc thẩm. Bản án, quyết định phúc thẩm của Tòa án có hiệu lực pháp luật.\r\n2. Bản án, quyết định của Tòa án đã có hiệu lực pháp luật mà phát hiện có vi phạm pháp luật nghiêm trọng hoặc có tình tiết mới theo quy định của Bộ luật này thì được xem xét lại theo trình tự giám đốc thẩm hoặc tái thẩm.', 'tt27', '2024-05-02 22:40:28', '2024-05-02 22:40:28'),
(28, 'Điều 28. Bảo đảm hiệu lực của bản án, quyết định của Tòa án\r\n1. Bản án, quyết định của Tòa án đã có hiệu lực pháp luật phải được cơ quan, tổ chức, cá nhân tôn trọng. Cơ quan, tổ chức, cá nhân hữu quan phải nghiêm chỉnh chấp hành.\r\n2. Trong phạm vi nhiệm vụ, quyền hạn, nghĩa vụ của mình, cơ quan, tổ chức, cá nhân có trách nhiệm phối hợp, tạo điều kiện và thực hiện yêu cầu của cơ quan, tổ chức, cá nhân có nhiệm vụ thi hành bản án, quyết định của Tòa án.', 'tt28', '2024-05-02 22:40:28', '2024-05-02 22:40:28'),
(29, 'Điều 29. Tiếng nói và chữ viết dùng trong tố tụng hình sự\r\nTiếng nói và chữ viết dùng trong tố tụng hình sự là tiếng Việt. Người tham gia tố tụng có quyền dùng tiếng nói và chữ viết của dân tộc mình, trường hợp này phải có phiên dịch.', 'tt29', '2024-05-02 22:40:28', '2024-05-02 22:40:28'),
(30, 'Điều 30. Giải quyết vấn đề dân sự trong vụ án hình sự\r\nViệc giải quyết vấn đề dân sự trong vụ án hình sự được tiến hành cùng với việc giải quyết vụ án hình sự. Trường hợp vụ án hình sự phải giải quyết vấn đề bồi thường thiệt hại, bồi hoàn mà chưa có điều kiện chứng minh và không ảnh hưởng đến việc giải quyết vụ án hình sự thì vấn đề dân sự có thể tách ra để giải quyết theo thủ tục tố tụng dân sự.', 'tt30', '2024-05-02 22:40:28', '2024-05-02 22:40:28'),
(31, 'Điều 31. Bảo đảm quyền được bồi thường của người bị thiệt hại trong hoạt động tố tụng hình sự\r\n1. Người bị giữ trong trường hợp khẩn cấp, người bị bắt, bị tạm giữ, tạm giam, khởi tố, điều tra, truy tố, xét xử, thi hành án oan, trái pháp luật có quyền được bồi thường thiệt hại về vật chất, tinh thần và phục hồi danh dự.\r\nNhà nước có trách nhiệm bồi thường thiệt hại và phục hồi danh dự, quyền lợi cho người bị giữ trong trường hợp khẩn cấp, người bị bắt, bị tạm giữ, tạm giam, khởi tố, điều tra, truy tố, xét xử, thi hành án oan, trái pháp luật do cơ quan, người có thẩm quyền tiến hành tố tụng gây ra.\r\n2. Người khác bị thiệt hại do cơ quan, người có thẩm quyền tiến hành tố tụng gây ra có quyền được Nhà nước bồi thường thiệt hại.', 'tt31', '2024-05-02 22:40:28', '2024-05-02 22:40:28'),
(32, 'Điều 32. Bảo đảm quyền khiếu nại, tố cáo trong tố tụng hình sự\r\nCá nhân, cơ quan, tổ chức có quyền khiếu nại, cá nhân có quyền tố cáo hành vi vi phạm pháp luật trong hoạt động tố tụng hình sự của cơ quan, người có thẩm quyền tiến hành tố tụng hoặc của bất cứ cá nhân nào thuộc các cơ quan đó.\r\nCơ quan, người có thẩm quyền phải tiếp nhận, xem xét và giải quyết khiếu nại, tố cáo kịp thời, đúng pháp luật; gửi văn bản kết quả giải quyết cho người khiếu nại, tố cáo, cơ quan, tổ chức khiếu nại và có biện pháp khắc phục.\r\nTrình tự, thủ tục, thẩm quyền giải quyết khiếu nại, tố cáo do Bộ luật này quy định.\r\nNghiêm cấm việc trả thù người khiếu nại, tố cáo hoặc lợi dụng quyền khiếu nại, tố cáo để vu khống người khác.', 'tt32', '2024-05-02 22:40:28', '2024-05-02 22:40:28'),
(33, 'Điều 33. Kiểm tra, giám sát trong tố tụng hình sự\r\n1. Cơ quan, người có thẩm quyền tiến hành tố tụng phải thường xuyên kiểm tra việc tiến hành các hoạt động tố tụng thuộc thẩm quyền; thực hiện kiểm soát giữa các cơ quan trong việc tiếp nhận, giải quyết nguồn tin về tội phạm, khởi tố, điều tra, truy tố, xét xử, thi hành án.\r\n2. Cơ quan nhà nước, Ủy ban Mặt trận Tổ quốc Việt Nam và các tổ chức thành viên của Mặt trận, đại biểu dân cử có quyền giám sát hoạt động của cơ quan, người có thẩm quyền tiến hành tố tụng; giám sát việc giải quyết khiếu nại, tố cáo của cơ quan, người có thẩm quyền tiến hành tố tụng.\r\nNếu phát hiện hành vi trái pháp luật của cơ quan, người có thẩm quyền tiến hành tố tụng thì cơ quan nhà nước, đại biểu dân cử có quyền yêu cầu, Ủy ban Mặt trận Tổ quốc Việt Nam và các tổ chức thành viên của Mặt trận có quyền kiến nghị với cơ quan có thẩm quyền tiến hành tố tụng xem xét, giải quyết theo quy định của Bộ luật này. Cơ quan có thẩm quyền tiến hành tố tụng phải xem xét, giải quyết và trả lời kiến nghị, yêu cầu đó theo quy định của pháp luật.', 'tt33', '2024-05-02 22:40:28', '2024-05-02 22:40:28'),
(34, 'Điều 34. Cơ quan tiến hành tố tụng và người tiến hành tố tụng\r\n1. Cơ quan tiến hành tố tụng gồm:\r\na) Cơ quan điều tra;\r\nb) Viện kiểm sát;\r\nc) Tòa án.\r\n2. Người tiến hành tố tụng gồm:\r\na) Thủ trưởng, Phó Thủ trưởng Cơ quan điều tra, Điều tra viên, Cán bộ điều tra;\r\nb) Viện trưởng, Phó Viện trưởng Viện kiểm sát, Kiểm sát viên, Kiểm tra viên;\r\nc) Chánh án, Phó Chánh án Tòa án, Thẩm phán, Hội thẩm, Thư ký Tòa án, Thẩm tra viên.', 'tt34', '2024-05-02 22:43:59', '2024-05-02 22:43:59'),
(35, 'Điều 35. Cơ quan và người được giao nhiệm vụ tiến hành một số hoạt động điều tra\r\n1. Cơ quan được giao nhiệm vụ tiến hành một số hoạt động điều tra gồm:\r\na) Các cơ quan của Bộ đội biên phòng;\r\nb) Các cơ quan của Hải quan;\r\nc) Các cơ quan của Kiểm lâm;\r\nd) Các cơ quan của lực lượng Cảnh sát biển;\r\nđ) Các cơ quan của Kiểm ngư;\r\ne) Các cơ quan của Công an nhân dân được giao nhiệm vụ tiến hành một số hoạt động điều tra;\r\ng) Các cơ quan khác trong Quân đội nhân dân được giao nhiệm vụ tiến hành một số hoạt động điều tra.\r\nCác cơ quan cụ thể được giao nhiệm vụ tiến hành một số hoạt động điều tra quy định tại khoản này được quy định tại Luật tổ chức cơ quan điều tra hình sự.\r\n2. Người được giao nhiệm vụ tiến hành một số hoạt động điều tra gồm:\r\na) Người được giao nhiệm vụ tiến hành một số hoạt động điều tra của Bộ đội biên phòng gồm Cục trưởng, Phó Cục trưởng Cục trinh sát biên phòng; Cục trưởng, Phó Cục trưởng Cục phòng, chống ma túy và tội phạm; Đoàn trưởng, Phó Đoàn trưởng Đoàn đặc nhiệm phòng, chống ma túy và tội phạm; Chỉ huy trưởng, Phó Chỉ huy trưởng Bộ đội biên phòng tỉnh, thành phố trực thuộc trung ương; Đồn trưởng, Phó Đồn trưởng Đồn biên phòng; Chỉ huy trưởng, Phó Chỉ huy trưởng Biên phòng Cửa khẩu cảng;\r\nb) Người được giao nhiệm vụ tiến hành một số hoạt động điều tra của Hải quan gồm Cục trưởng, Phó Cục trưởng Cục điều tra chống buôn lậu; Cục trưởng, Phó Cục trưởng Cục kiểm tra sau thông quan; Cục trưởng, Phó Cục trưởng Cục Hải quan tỉnh, liên tỉnh, thành phố trực thuộc trung ương; Chi cục trưởng, Phó Chi cục trưởng Chi cục Hải quan cửa khẩu;\r\nc) Người được giao nhiệm vụ tiến hành một số hoạt động điều tra của Kiểm lâm gồm Cục trưởng, Phó Cục trưởng Cục Kiểm lâm; Chi cục trưởng, Phó Chi cục trưởng Chi cục Kiểm lâm; Hạt trưởng, Phó Hạt trưởng Hạt Kiểm lâm;\r\nd) Người được giao nhiệm vụ tiến hành một số hoạt động điều tra của lực lượng Cảnh sát biển gồm Tư lệnh, Phó Tư lệnh Cảnh sát biển; Tư lệnh vùng, Phó Tư lệnh vùng Cảnh sát biển; Cục trưởng, Phó Cục trưởng Cục Nghiệp vụ và pháp luật; Đoàn trưởng, Phó Đoàn trưởng Đoàn đặc nhiệm phòng, chống tội phạm ma túy; Hải đoàn trưởng, Phó Hải đoàn trưởng; Hải đội trưởng, Phó Hải đội trưởng; Đội trưởng, Phó Đội trưởng Đội nghiệp vụ Cảnh sát biển;\r\nđ) Người được giao nhiệm vụ tiến hành một số hoạt động điều tra của Kiểm ngư gồm Cục trưởng, Phó Cục trưởng Cục Kiểm ngư; Chi cục trưởng, Phó Chi cục trưởng Chi cục Kiểm ngư vùng;\r\ne) Người được giao nhiệm vụ tiến hành một số hoạt động điều tra của các cơ quan khác trong Công an nhân dân gồm Giám đốc, Phó giám đốc Cảnh sát phòng cháy, chữa cháy; Cục trưởng, Phó Cục trưởng, Trưởng phòng, Phó Trưởng phòng các cơ quan được giao nhiệm vụ tiến hành một số hoạt động điều tra của Công an nhân dân, Giám thị, Phó Giám thị Trại giam theo quy định của Luật tổ chức cơ quan điều tra hình sự;\r\ng) Người được giao nhiệm vụ tiến hành một số hoạt động điều tra của các cơ quan khác trong Quân đội nhân dân gồm Giám thị, Phó Giám thị Trại giam; Thủ trưởng đơn vị độc lập cấp trung đoàn và tương đương.\r\nh) Cán bộ điều tra thuộc các cơ quan quy định tại khoản 1 Điều này.', 'tt35', '2024-05-02 22:43:59', '2024-05-02 22:43:59'),
(36, 'Điều 36. Nhiệm vụ, quyền hạn và trách nhiệm của Thủ trưởng, Phó Thủ trưởng Cơ quan điều tra\r\n1. Thủ trưởng Cơ quan điều tra có những nhiệm vụ, quyền hạn:\r\na) Trực tiếp tổ chức và chỉ đạo việc thụ lý, giải quyết nguồn tin về tội phạm, việc khởi tố, điều tra của Cơ quan điều tra;\r\nb) Quyết định phân công hoặc thay đổi Phó Thủ trưởng Cơ quan điều tra, thụ lý, giải quyết nguồn tin về tội phạm, kiểm tra việc khởi tố, điều tra vụ án hình sự của Phó Thủ trưởng Cơ quan điều tra; quyết định thay đổi hoặc hủy bỏ các quyết định không có căn cứ và trái pháp luật của Phó Thủ trưởng Cơ quan điều tra.\r\nc) Quyết định phân công hoặc thay đổi Điều tra viên, Cán bộ điều tra; kiểm tra các hoạt động thụ lý, giải quyết nguồn tin về tội phạm, khởi tố, điều tra vụ án hình sự của Điều tra viên, Cán bộ điều tra; quyết định thay đổi hoặc hủy bỏ các quyết định không có căn cứ và trái pháp luật của Điều tra viên.\r\nd) Giải quyết khiếu nại, tố cáo thuộc thẩm quyền của Cơ quan điều tra.\r\nKhi vắng mặt, Thủ trưởng Cơ quan điều tra ủy quyền cho một Phó Thủ trưởng Cơ quan điều tra thực hiện nhiệm vụ, quyền hạn của Thủ trưởng Cơ quan điều tra. Phó Thủ trưởng chịu trách nhiệm trước Thủ trưởng về nhiệm vụ được ủy quyền.\r\n2. Khi tiến hành tố tụng hình sự, Thủ trưởng Cơ quan điều tra có những nhiệm vụ, quyền hạn:\r\na) Quyết định tạm đình chỉ việc giải quyết tố giác, tin báo về tội phạm, kiến nghị khởi tố; quyết định khởi tố, không khởi tố, bổ sung hoặc thay đổi quyết định khởi tố vụ án; quyết định khởi tố, bổ sung hoặc thay đổi quyết định khởi tố bị can; quyết định nhập hoặc tách vụ án; quyết định ủy thác điều tra;\r\nb) Quyết định áp dụng, thay đổi, hủy bỏ biện pháp ngăn chặn, biện pháp cưỡng chế, biện pháp điều tra tố tụng đặc biệt theo quy định của Bộ luật này;\r\nc) Quyết định truy nã, đình nã bị can, khám xét, thu giữ, tạm giữ, xử lý vật chứng;\r\nd) Quyết định trưng cầu giám định, giám định bổ sung hoặc giám định lại, khai quật tử thi, thực nghiệm điều tra, thay đổi hoặc yêu cầu thay đổi người giám định. Yêu cầu định giá, định giá lại tài sản, yêu cầu thay đổi người định giá tài sản.\r\nđ) Trực tiếp kiểm tra, xác minh nguồn tin về tội phạm và tiến hành các biện pháp điều tra;\r\ne) Kết luận điều tra vụ án;\r\ng) Quyết định tạm đình chỉ điều tra, đình chỉ điều tra, phục hồi điều tra vụ án, bị can;\r\nh) Ra các lệnh, quyết định và tiến hành các hoạt động tố tụng khác thuộc thẩm quyền của Cơ quan điều tra.\r\n3. Khi được phân công tiến hành việc khởi tố, điều tra vụ án hình sự, Phó Thủ trưởng Cơ quan điều tra có những nhiệm vụ, quyền hạn quy định tại khoản 1 và khoản 2 Điều này, trừ quy định tại điểm b khoản 1 Điều này. Phó Thủ trưởng Cơ quan điều tra không được giải quyết khiếu nại, tố cáo về hành vi, quyết định của mình.\r\n4. Thủ trưởng, Phó Thủ trưởng Cơ quan điều tra phải chịu trách nhiệm trước pháp luật về hành vi, quyết định của mình. Thủ trưởng, Phó Thủ trưởng Cơ quan điều tra không được ủy quyền cho Điều tra viên thực hiện nhiệm vụ, quyền hạn của mình.', 'tt36', '2024-05-02 22:43:59', '2024-05-02 22:43:59'),
(37, 'Điều 37. Nhiệm vụ, quyền hạn và trách nhiệm của Điều tra viên\r\n1. Điều tra viên được phân công tiến hành hoạt động khởi tố, điều tra vụ án hình sự có những nhiệm vụ, quyền hạn:\r\na) Trực tiếp kiểm tra, xác minh và lập hồ sơ giải quyết nguồn tin về tội phạm;\r\nb) Lập hồ sơ vụ án hình sự;\r\nc) Yêu cầu hoặc đề nghị cử, thay đổi người bào chữa; yêu cầu cử, thay đổi người phiên dịch, người dịch thuật;\r\nd) Triệu tập và hỏi cung bị can; triệu tập và lấy lời khai người tố giác, báo tin về tội phạm, người bị tố giác, kiến nghị khởi tố, người đại diện theo pháp luật của pháp nhân; lấy lời khai người bị giữ trong trường hợp khẩn cấp, người bị bắt, người bị tạm giữ; triệu tập và lấy lời khai của người làm chứng, bị hại, đương sự;\r\nđ) Quyết định áp giải người bị giữ trong trường hợp khẩn cấp, người bị bắt, bị tạm giữ, bị can; quyết định dẫn giải người làm chứng, người bị tố giác, người bị kiến nghị khởi tố, bị hại; quyết định giao người dưới 18 tuổi cho cơ quan, tổ chức, cá nhân có trách nhiệm giám sát; quyết định thay đổi người giám sát người dưới 18 tuổi phạm tội;\r\ne) Thi hành lệnh giữ người trong trường hợp khẩn cấp, lệnh hoặc quyết định bắt, tạm giữ, tạm giam, khám xét, thu giữ, tạm giữ, kê biên tài sản, phong tỏa tài khoản, xử lý vật chứng;\r\ng) Tiến hành khám nghiệm hiện trường, khai quật tử thi, khám nghiệm tử thi, xem xét dấu vết trên thân thể, đối chất, nhận dạng, thực nghiệm điều tra;\r\nh) Thực hiện nhiệm vụ, quyền hạn tố tụng khác thuộc thẩm quyền của Cơ quan điều tra theo sự phân công của Thủ trưởng Cơ quan điều tra theo quy định của Bộ luật này.\r\n2. Điều tra viên phải chịu trách nhiệm trước pháp luật và trước Thủ trưởng, Phó Thủ trưởng Cơ quan điều tra về hành vi, quyết định của mình.', 'tt37', '2024-05-02 22:43:59', '2024-05-02 22:43:59'),
(38, 'Điều 38. Nhiệm vụ, quyền hạn và trách nhiệm của Cán bộ điều tra của Cơ quan điều tra\r\n1. Cán bộ điều tra thực hiện những nhiệm vụ, quyền hạn sau đây theo sự phân công của Điều tra viên:\r\na) Ghi biên bản lấy lời khai, ghi biên bản hỏi cung và ghi các biên bản khác khi Điều tra viên tiến hành kiểm tra, xác minh nguồn tin về tội phạm và điều tra vụ án hình sự;\r\nb) Giao, chuyển, gửi các lệnh, quyết định và các văn bản tố tụng khác theo quy định của Bộ luật này;\r\nc) Giúp Điều tra viên trong việc lập hồ sơ giải quyết nguồn tin về tội phạm, hồ sơ vụ án và thực hiện hoạt động tố tụng khác.\r\n2. Cán bộ điều tra phải chịu trách nhiệm trước pháp luật và trước Thủ trưởng, Phó Thủ trưởng Cơ quan điều tra, Điều tra viên về hành vi của mình.', 'tt38', '2024-05-02 22:43:59', '2024-05-02 22:43:59'),
(39, 'Điều 39. Nhiệm vụ, quyền hạn và trách nhiệm của cấp trưởng, cấp phó, cán bộ điều tra của các cơ quan của Bộ đội biên phòng, Hải quan, Kiểm lâm, lực lượng Cảnh sát biển, Kiểm ngư được giao nhiệm vụ tiến hành một số hoạt động điều tra\r\n1. Cấp trưởng các cơ quan được giao nhiệm vụ tiến hành một số hoạt động điều tra quy định tại các điểm a, b, c, d và đ khoản 2 Điều 35 của Bộ luật này có những nhiệm vụ, quyền hạn:\r\na) Trực tiếp chỉ đạo hoạt động thụ lý, giải quyết nguồn tin về tội phạm, khởi tố, điều tra vụ án hình sự theo thẩm quyền;\r\nb) Quyết định phân công hoặc thay đổi cấp phó, cán bộ điều tra trong việc thụ lý, giải quyết nguồn tin về tội phạm, khởi tố, điều tra vụ án hình sự;\r\nc) Kiểm tra hoạt động thụ lý, giải quyết nguồn tin về tội phạm, khởi tố, điều tra vụ án hình sự của cấp phó và cán bộ điều tra;\r\nd) Quyết định thay đổi hoặc hủy bỏ quyết định không có căn cứ và trái pháp luật của cấp phó, cán bộ điều tra;\r\nđ) Quyết định giao người bị buộc tội là người dưới 18 tuổi cho người đại diện của họ giám sát.\r\nKhi vắng mặt, cấp trưởng ủy quyền cho một cấp phó được thực hiện nhiệm vụ, quyền hạn của cấp trưởng. Cấp phó chịu trách nhiệm trước cấp trưởng về nhiệm vụ được ủy quyền. Cấp trưởng, cấp phó không được ủy quyền cho cán bộ điều tra thực hiện nhiệm vụ, quyền hạn của mình.\r\n2. Khi tiến hành tố tụng hình sự đối với tội phạm ít nghiêm trọng trong trường hợp phạm tội quả tang, chứng cứ và lý lịch người phạm tội rõ ràng, những người quy định tại các điểm a, b, c, d và đ khoản 2 Điều 35 của Bộ luật này có những nhiệm vụ, quyền hạn:\r\na) Thu thập chứng cứ, tài liệu, đồ vật từ những người có liên quan để kiểm tra, xác minh nguồn tin về tội phạm;\r\nb) Quyết định tạm đình chỉ việc giải quyết tố giác, tin báo về tội phạm, kiến nghị khởi tố; quyết định khởi tố, không khởi tố, thay đổi hoặc bổ sung quyết định khởi tố vụ án; quyết định khởi tố, thay đổi hoặc bổ sung quyết định khởi tố bị can;\r\nc) Trực tiếp tổ chức và chỉ đạo việc khám nghiệm hiện trường;\r\nd) Quyết định trưng cầu giám định, yêu cầu định giá tài sản; quyết định khám xét, thu giữ, tạm giữ và bảo quản vật chứng, tài liệu liên quan trực tiếp đến vụ án;\r\nđ) Triệu tập và hỏi cung bị can; triệu tập và lấy lời khai bị hại, đương sự; triệu tập và lấy lời khai người tố giác, báo tin về tội phạm, người bị tố giác, kiến nghị khởi tố; triệu tập và lấy lời khai người làm chứng; lấy lời khai người bị giữ trong trường hợp khẩn cấp;\r\ne) Quyết định áp dụng biện pháp ngăn chặn, biện pháp cưỡng chế theo quy định của Bộ luật này;\r\ng) Kết luận điều tra, đề nghị truy tố hoặc kết luận điều tra và quyết định đình chỉ điều tra; quyết định tạm đình chỉ điều tra; quyết định phục hồi điều tra.\r\n3. Khi tiến hành tố tụng hình sự đối với tội phạm nghiêm trọng, rất nghiêm trọng, đặc biệt nghiêm trọng hoặc tội phạm ít nghiêm trọng nhưng phức tạp, những người được quy định tại các điểm a, b, c, d và đ khoản 2 Điều 35 của Bộ luật này có những nhiệm vụ, quyền hạn:\r\na) Thu thập chứng cứ, tài liệu, đồ vật từ những người có liên quan để kiểm tra, xác minh nguồn tin về tội phạm;\r\nb) Quyết định tạm đình chỉ việc giải quyết tố giác, tin báo về tội phạm, kiến nghị khởi tố; quyết định khởi tố, không khởi tố, thay đổi hoặc bổ sung quyết định khởi tố vụ án;\r\nc) Quyết định khám xét, thu giữ, tạm giữ và bảo quản vật chứng, tài liệu liên quan trực tiếp đến vụ án;\r\nd) Triệu tập và lấy lời khai người làm chứng, bị hại, đương sự.\r\n4. Cán bộ điều tra có những nhiệm vụ, quyền hạn:\r\na) Lập hồ sơ giải quyết nguồn tin về tội phạm; lấy lời khai của những người có liên quan để kiểm tra, xác minh nguồn tin về tội phạm;\r\nb) Lập hồ sơ vụ án hình sự;\r\nc) Hỏi cung bị can; lấy lời khai người tố giác, báo tin về tội phạm, người bị tố giác, người bị kiến nghị khởi tố, người bị giữ trong trường hợp khẩn cấp, người bị bắt, người bị tạm giữ, người làm chứng, bị hại, đương sự;\r\nd) Tiến hành khám nghiệm hiện trường; thi hành lệnh khám xét, thu giữ, tạm giữ và bảo quản vật chứng, tài liệu liên quan trực tiếp đến vụ án.\r\n5. Trong phạm vi trách nhiệm của mình, cấp trưởng, cấp phó, cán bộ điều tra của các cơ quan của Bộ đội biên phòng, Hải quan, Kiểm lâm, lực lượng Cảnh sát biển, Kiểm ngư được giao nhiệm vụ tiến hành một số hoạt động điều tra phải chịu trách nhiệm trước pháp luật về hành vi, quyết định của mình. Cấp trưởng, cấp phó không được ủy quyền cho cán bộ điều tra thực hiện nhiệm vụ, quyền hạn của mình.', 'tt39', '2024-05-02 22:43:59', '2024-05-02 22:43:59'),
(40, 'Điều 40. Nhiệm vụ, quyền hạn và trách nhiệm của cấp trưởng, cấp phó, cán bộ điều tra của các cơ quan khác của Công an nhân dân, Quân đội nhân dân được giao nhiệm vụ tiến hành một số hoạt động điều tra\r\n1. Cấp trưởng các cơ quan được giao nhiệm vụ tiến hành một số hoạt động điều tra quy định tại điểm e và điểm g khoản 2 Điều 35 của Bộ luật này có những nhiệm vụ, quyền hạn:\r\na) Trực tiếp chỉ đạo hoạt động khởi tố, điều tra vụ án hình sự theo thẩm quyền;\r\nb) Quyết định phân công hoặc thay đổi cấp phó, cán bộ điều tra trong việc khởi tố, điều tra vụ án hình sự;\r\nc) Kiểm tra hoạt động thụ lý, giải quyết nguồn tin về tội phạm, khởi tố, điều tra vụ án hình sự của cấp phó và cán bộ điều tra;\r\nd) Quyết định thay đổi hoặc hủy bỏ quyết định không có căn cứ và trái pháp luật của cấp phó, cán bộ điều tra.\r\nKhi cấp trưởng vắng mặt, một cấp phó được ủy quyền thực hiện nhiệm vụ, quyền hạn của cấp trưởng và chịu trách nhiệm trước cấp trưởng về nhiệm vụ được ủy quyền.\r\n2. Khi tiến hành tố tụng hình sự, những người được quy định tại điểm e và điểm g khoản 2 Điều 35 của Bộ luật này có những nhiệm vụ, quyền hạn:\r\na) Thu thập chứng cứ, tài liệu, đồ vật từ những người có liên quan để kiểm tra, xác minh nguồn tin về tội phạm;\r\nb) Quyết định tạm đình chỉ việc giải quyết nguồn tin về tội phạm; quyết định khởi tố, không khởi tố, thay đổi hoặc bổ sung quyết định khởi tố vụ án;\r\nc) Trực tiếp tổ chức và chỉ đạo việc khám nghiệm hiện trường;\r\nd) Quyết định khám xét, thu giữ, tạm giữ và bảo quản vật chứng, tài liệu liên quan trực tiếp đến vụ án;\r\nđ) Triệu tập và lấy lời khai người tố giác, báo tin về tội phạm, người bị tố giác, người bị kiến nghị khởi tố, người làm chứng, bị hại, đương sự.\r\n3. Cán bộ điều tra có những nhiệm vụ, quyền hạn:\r\na) Lập hồ sơ giải quyết nguồn tin về tội phạm; lấy lời khai của những người có liên quan để kiểm tra, xác minh nguồn tin về tội phạm;\r\nb) Lập hồ sơ vụ án hình sự;\r\nc) Lấy lời khai người tố giác, báo tin về tội phạm, người bị tố giác, người bị kiến nghị khởi tố, người làm chứng, bị hại, đương sự;\r\nd) Tiến hành khám nghiệm hiện trường; thi hành lệnh khám xét, thu giữ, tạm giữ và bảo quản vật chứng, tài liệu liên quan trực tiếp đến vụ án;\r\nđ) Giao, gửi các lệnh, quyết định và các văn bản tố tụng khác theo quy định của Bộ luật này.\r\n4. Trong phạm vi trách nhiệm của mình, cấp trưởng, cấp phó, cán bộ điều tra của các cơ quan của Công an nhân dân, Quân đội nhân dân được giao nhiệm vụ tiến hành một số hoạt động điều tra phải chịu trách nhiệm trước pháp luật về hành vi, quyết định của mình. Cấp trưởng, cấp phó không được ủy quyền cho cán bộ điều tra thực hiện nhiệm vụ, quyền hạn của mình.', 'tt40', '2024-05-02 22:43:59', '2024-05-02 22:43:59'),
(41, 'Điều 41. Nhiệm vụ, quyền hạn và trách nhiệm của Viện trưởng, Phó Viện trưởng Viện kiểm sát\r\n1. Viện trưởng Viện kiểm sát có những nhiệm vụ, quyền hạn:\r\na) Trực tiếp tổ chức và chỉ đạo hoạt động thực hành quyền công tố và kiểm sát việc tuân theo pháp luật trong tố tụng hình sự;\r\nb) Quyết định phân công hoặc thay đổi Phó Viện trưởng Viện kiểm sát; kiểm tra hoạt động thực hành quyền công tố và kiểm sát việc tuân theo pháp luật trong tố tụng hình sự của Phó Viện trưởng Viện kiểm sát; quyết định thay đổi hoặc hủy bỏ quyết định không có căn cứ và trái pháp luật của Phó Viện trưởng Viện kiểm sát;\r\nc) Quyết định phân công hoặc thay đổi Kiểm sát viên, Kiểm tra viên; kiểm tra hoạt động thực hành quyền công tố và kiểm sát việc tuân theo pháp luật trong tố tụng hình sự của Kiểm sát viên, Kiểm tra viên; quyết định thay đổi hoặc hủy bỏ quyết định không có căn cứ và trái pháp luật của Kiểm sát viên;\r\nd) Quyết định rút, đình chỉ hoặc hủy bỏ quyết định không có căn cứ và trái pháp luật của Viện kiểm sát cấp dưới;\r\nđ) Giải quyết khiếu nại, tố cáo thuộc thẩm quyền của Viện kiểm sát.\r\nKhi vắng mặt, Viện trưởng Viện kiểm sát ủy quyền cho một Phó Viện trưởng Viện kiểm sát thực hiện nhiệm vụ, quyền hạn của Viện trưởng và chịu trách nhiệm trước Viện trưởng Viện kiểm sát về nhiệm vụ được ủy quyền.\r\n2. Khi thực hành quyền công tố và kiểm sát việc tuân theo pháp luật trong hoạt động tố tụng hình sự, Viện trưởng Viện kiểm sát có những nhiệm vụ, quyền hạn:\r\na) Yêu cầu Cơ quan điều tra, cơ quan được giao nhiệm vụ tiến hành một số hoạt động điều tra tiếp nhận, giải quyết nguồn tin về tội phạm, khởi tố hoặc thay đổi, bổ sung quyết định khởi tố vụ án hình sự, khởi tố bị can; quyết định khởi tố, không khởi tố, thay đổi, bổ sung quyết định khởi tố vụ án, khởi tố bị can theo quy định của Bộ luật này;\r\nb) Quyết định tạm đình chỉ việc giải quyết nguồn tin về tội phạm; quyết định khởi tố, không khởi tố, bổ sung hoặc thay đổi quyết định khởi tố vụ án; quyết định khởi tố, bổ sung hoặc thay đổi quyết định khởi tố bị can; quyết định nhập, tách vụ án;\r\nc) Quyết định áp dụng, thay đổi, hủy bỏ biện pháp ngăn chặn, biện pháp cưỡng chế, biện pháp điều tra tố tụng đặc biệt; quyết định việc gia hạn kiểm tra và xác minh nguồn tin về tội phạm, gia hạn tạm giữ, gia hạn điều tra, gia hạn tạm giam, gia hạn truy tố;\r\nd) Quyết định khám xét, thu giữ, tạm giữ, xử lý vật chứng;\r\nđ) Quyết định trưng cầu giám định, giám định bổ sung hoặc giám định lại, thực nghiệm điều tra; thay đổi hoặc yêu cầu thay đổi người giám định. Yêu cầu định giá, định giá lại tài sản, yêu cầu thay đổi người định giá tài sản;\r\ne) Yêu cầu Thủ trưởng Cơ quan điều tra, cấp trưởng cơ quan được giao nhiệm vụ tiến hành một số hoạt động điều tra thay đổi Điều tra viên, Cán bộ điều tra;\r\ng) Phê chuẩn hoặc không phê chuẩn quyết định, lệnh của Cơ quan điều tra, cơ quan được giao nhiệm vụ tiến hành một số hoạt động điều tra;\r\nh) Quyết định hủy bỏ các quyết định, lệnh không có căn cứ và trái pháp luật của Cơ quan điều tra, cơ quan được giao nhiệm vụ tiến hành một số hoạt động điều tra;\r\ni) Giải quyết tranh chấp về thẩm quyền giải quyết nguồn tin về tội phạm, khởi tố, điều tra; quyết định chuyển vụ án;\r\nk) Quyết định áp dụng, đình chỉ biện pháp bắt buộc chữa bệnh;\r\nl) Quyết định áp dụng thủ tục rút gọn hoặc hủy bỏ quyết định áp dụng thủ tục rút gọn;\r\nm) Quyết định truy tố bị can, trả hồ sơ để điều tra bổ sung hoặc điều tra lại;\r\nn) Yêu cầu phục hồi điều tra; quyết định tạm đình chỉ hoặc đình chỉ vụ án, đình chỉ hoặc tạm đình chỉ vụ án đối với bị can; quyết định hủy bỏ quyết định tạm đình chỉ việc giải quyết nguồn tin về tội phạm; quyết định phục hồi điều tra vụ án, phục hồi điều tra đối với bị can, phục hồi vụ án, phục hồi vụ án đối với bị can;\r\no) Kháng nghị theo thủ tục phúc thẩm, giám đốc thẩm, tái thẩm bản án, quyết định của Tòa án theo quy định của Bộ luật này;\r\np) Thực hiện quyền kiến nghị theo quy định của pháp luật;\r\nq) Ban hành quyết định, lệnh và tiến hành các hoạt động tố tụng khác thuộc thẩm quyền của Viện kiểm sát.\r\n3. Khi được phân công thực hành quyền công tố và kiểm sát việc tuân theo pháp luật trong tố tụng hình sự, Phó Viện trưởng Viện kiểm sát có những nhiệm vụ, quyền hạn quy định tại khoản 1 và khoản 2 Điều này, trừ quy định tại điểm b khoản 1 Điều này. Phó Viện trưởng Viện kiểm sát không được giải quyết khiếu nại, tố cáo về hành vi, quyết định của mình.\r\n4. Viện trưởng, Phó Viện trưởng Viện kiểm sát phải chịu trách nhiệm trước pháp luật về hành vi, quyết định của mình. Viện trưởng, Phó Viện trưởng Viện kiểm sát không được ủy quyền cho Kiểm sát viên thực hiện nhiệm vụ, quyền hạn của mình.', 'tt41', '2024-05-02 22:43:59', '2024-05-02 22:43:59'),
(42, 'Điều 42. Nhiệm vụ, quyền hạn và trách nhiệm của Kiểm sát viên\r\n1. Kiểm sát viên được phân công thực hành quyền công tố và kiểm sát việc tuân theo pháp luật trong tố tụng hình sự có những nhiệm vụ, quyền hạn:\r\na) Kiểm sát việc tiếp nhận, giải quyết nguồn tin về tội phạm của cơ quan, người có thẩm quyền;\r\nb) Trực tiếp giải quyết và lập hồ sơ giải quyết nguồn tin về tội phạm;\r\nc) Kiểm sát việc thụ lý, giải quyết nguồn tin về tội phạm, khởi tố, áp dụng biện pháp ngăn chặn, biện pháp cưỡng chế; kiểm sát việc lập hồ sơ giải quyết nguồn tin về tội phạm, việc lập hồ sơ vụ án của cơ quan, người có thẩm quyền điều tra; kiểm sát hoạt động khởi tố, điều tra của Cơ quan điều tra, cơ quan được giao nhiệm vụ tiến hành một số hoạt động điều tra;\r\nd) Trực tiếp kiểm sát việc khám nghiệm hiện trường, khám nghiệm tử thi, đối chất, nhận dạng, nhận biết giọng nói, thực nghiệm điều tra, khám xét;\r\nđ) Kiểm sát việc tạm đình chỉ, phục hồi việc giải quyết nguồn tin về tội phạm; việc tạm đình chỉ điều tra, đình chỉ điều tra, phục hồi điều tra, kết thúc điều tra;\r\ne) Đề ra yêu cầu điều tra; yêu cầu Cơ quan điều tra truy nã, đình nã bị can;\r\ng) Triệu tập và hỏi cung bị can; triệu tập và lấy lời khai người tố giác, báo tin về tội phạm, người bị tố giác, người bị kiến nghị khởi tố, người đại diện theo pháp luật của pháp nhân, người làm chứng, bị hại, đương sự; lấy lời khai người bị giữ trong trường hợp khẩn cấp;\r\nh) Quyết định áp giải người bị bắt, bị can; quyết định dẫn giải người làm chứng, người bị tố giác, người bị kiến nghị khởi tố, bị hại; quyết định giao người dưới 18 tuổi cho cơ quan, tổ chức, cá nhân có trách nhiệm giám sát; quyết định thay đổi người giám sát người dưới 18 tuổi phạm tội;\r\ni) Trực tiếp tiến hành một số hoạt động điều tra theo quy định của Bộ luật này;\r\nk) Yêu cầu thay đổi người có thẩm quyền tiến hành tố tụng; yêu cầu hoặc đề nghị cử, thay đổi người bào chữa; yêu cầu cử, đề nghị thay đổi người phiên dịch, người dịch thuật;\r\nl) Tiến hành tố tụng tại phiên tòa; công bố cáo trạng hoặc quyết định truy tố theo thủ tục rút gọn, các quyết định khác của Viện kiểm sát về việc buộc tội đối với bị cáo; xét hỏi, đưa ra chứng cứ, tài liệu, đồ vật, luận tội, tranh luận, phát biểu quan điểm về việc giải quyết vụ án tại phiên tòa, phiên họp;\r\nm) Kiểm sát việc tuân theo pháp luật trong giai đoạn xét xử của Tòa án và những người tham gia tố tụng; kiểm sát bản án, quyết định và các văn bản tố tụng khác của Tòa án;\r\nn) Kiểm sát việc thi hành bản án, quyết định của Tòa án;\r\no) Thực hiện quyền yêu cầu, kiến nghị theo quy định của pháp luật;\r\np) Thực hiện nhiệm vụ, quyền hạn tố tụng khác thuộc thẩm quyền của Viện kiểm sát theo sự phân công của Viện trưởng Viện kiểm sát theo quy định của Bộ luật này.\r\n2. Kiểm sát viên phải chịu trách nhiệm trước pháp luật và trước Viện trưởng Viện kiểm sát, Phó Viện trưởng Viện kiểm sát về hành vi, quyết định của mình.', 'tt42', '2024-05-02 22:43:59', '2024-05-02 22:43:59'),
(43, 'Điều 43. Nhiệm vụ, quyền hạn và trách nhiệm của Kiểm tra viên\r\n1. Kiểm tra viên thực hiện những nhiệm vụ, quyền hạn sau đây theo sự phân công của Kiểm sát viên:\r\na) Ghi biên bản lấy lời khai, ghi biên bản hỏi cung và ghi các biên bản khác trong tố tụng hình sự;\r\nb) Giao, chuyển, gửi các lệnh, quyết định và các văn bản tố tụng khác theo quy định của Bộ luật này;\r\nc) Giúp Kiểm sát viên trong việc lập hồ sơ kiểm sát, hồ sơ giải quyết nguồn tin về tội phạm và tiến hành hoạt động tố tụng khác.\r\n2. Kiểm tra viên phải chịu trách nhiệm trước pháp luật và trước Viện trưởng, Phó Viện trưởng Viện kiểm sát và Kiểm sát viên về hành vi của mình.', 'tt43', '2024-05-02 22:43:59', '2024-05-02 22:43:59');
INSERT INTO `bltt_chatbot_responses` (`chatbot_responses_id`, `chatbot_responses`, `intent_tt_group_name`, `created_datetime`, `updated_datetime`) VALUES
(44, 'Điều 44. Nhiệm vụ, quyền hạn và trách nhiệm của Chánh án, Phó Chánh án Tòa án\r\n1. Chánh án Tòa án có những nhiệm vụ, quyền hạn:\r\na) Trực tiếp tổ chức việc xét xử vụ án hình sự; quyết định giải quyết tranh chấp về thẩm quyền xét xử;\r\nb) Quyết định phân công Phó Chánh án Tòa án, Thẩm phán, Hội thẩm giải quyết, xét xử vụ án hình sự; quyết định phân công Thư ký Tòa án tiến hành tố tụng đối với vụ án hình sự; quyết định phân công Thẩm tra viên thẩm tra hồ sơ vụ án hình sự;\r\nc) Quyết định thay đổi Thẩm phán, Hội thẩm, Thư ký Tòa án trước khi mở phiên tòa;\r\nd) Ra quyết định thi hành án hình sự;\r\nđ) Quyết định hoãn chấp hành án phạt tù;\r\ne) Quyết định tạm đình chỉ chấp hành án phạt tù;\r\ng) Quyết định xoá án tích;\r\nh) Giải quyết khiếu nại, tố cáo thuộc thẩm quyền của Tòa án.\r\nKhi vắng mặt, Chánh án Tòa án ủy quyền cho một Phó Chánh án Tòa án thực hiện nhiệm vụ, quyền hạn của Chánh án. Phó Chánh án Tòa án phải chịu trách nhiệm trước Chánh án Tòa án về nhiệm vụ được ủy quyền.\r\n2. Khi tiến hành việc giải quyết vụ án hình sự, Chánh án Tòa án có những nhiệm vụ, quyền hạn:\r\na) Quyết định áp dụng, thay đổi hoặc hủy bỏ biện pháp tạm giam, xử lý vật chứng;\r\nb) Quyết định áp dụng, đình chỉ biện pháp bắt buộc chữa bệnh;\r\nc) Quyết định áp dụng thủ tục rút gọn hoặc hủy bỏ quyết định áp dụng thủ tục rút gọn;\r\nd) Kiến nghị, kháng nghị theo thủ tục giám đốc thẩm bản án, quyết định đã có hiệu lực pháp luật của Tòa án;\r\nđ) Quyết định và tiến hành hoạt động tố tụng khác thuộc thẩm quyền của Tòa án;\r\ne) Tiến hành hoạt động tố tụng khác theo quy định của Bộ luật này.\r\n3. Khi được phân công giải quyết, xét xử vụ án hình sự, Phó Chánh án Tòa án có những nhiệm vụ, quyền hạn quy định tại khoản 1 và khoản 2 Điều này, trừ quy định tại điểm b khoản 1 Điều này. Phó Chánh án Tòa án không được giải quyết khiếu nại, tố cáo về hành vi, quyết định của mình.\r\n4. Chánh án, Phó Chánh án Tòa án phải chịu trách nhiệm trước pháp luật về hành vi, quyết định của mình. Chánh án, Phó Chánh án Tòa án không được ủy quyền cho Thẩm phán thực hiện nhiệm vụ, quyền hạn của mình.', 'tt44', '2024-05-02 22:45:27', '2024-05-02 22:45:27'),
(45, 'Điều 45. Nhiệm vụ, quyền hạn và trách nhiệm của Thẩm phán\r\n1. Thẩm phán được phân công giải quyết, xét xử vụ án hình sự có những nhiệm vụ, quyền hạn:\r\na) Nghiên cứu hồ sơ vụ án trước khi mở phiên tòa;\r\nb) Tiến hành xét xử vụ án;\r\nc) Tiến hành hoạt động tố tụng và biểu quyết những vấn đề thuộc thẩm quyền của Hội đồng xét xử;\r\nd) Tiến hành hoạt động tố tụng khác thuộc thẩm quyền của Tòa án theo sự phân công của Chánh án Tòa án.\r\n2. Thẩm phán chủ tọa phiên tòa có những nhiệm vụ, quyền hạn quy định tại khoản 1 Điều này và những nhiệm vụ, quyền hạn:\r\na) Quyết định áp dụng, thay đổi, hủy bỏ biện pháp ngăn chặn, biện pháp cưỡng chế, trừ biện pháp tạm giam;\r\nb) Quyết định trả hồ sơ để điều tra bổ sung;\r\nc) Quyết định đưa vụ án ra xét xử; quyết định đình chỉ hoặc tạm đình chỉ vụ án;\r\nd) Điều hành việc xét xử vụ án, tranh tụng tại phiên tòa;\r\nđ) Quyết định trưng cầu giám định, giám định bổ sung hoặc giám định lại, thực nghiệm điều tra; thay đổi hoặc yêu cầu thay đổi người giám định; yêu cầu định giá tài sản, yêu cầu thay đổi người định giá tài sản;\r\ne) Yêu cầu hoặc đề nghị cử, thay đổi người bào chữa; thay đổi người giám sát người dưới 18 tuổi phạm tội; yêu cầu cử, thay đổi người phiên dịch, người dịch thuật;\r\ng) Quyết định triệu tập những người cần xét hỏi đến phiên tòa;\r\nh) Thực hiện nhiệm vụ, quyền hạn tố tụng khác thuộc thẩm quyền của Tòa án theo sự phân công của Chánh án Tòa án theo quy định của Bộ luật này.\r\n3. Thẩm phán phải chịu trách nhiệm trước pháp luật về hành vi, quyết định của mình.', 'tt45', '2024-05-02 22:45:27', '2024-05-02 22:45:27'),
(46, 'Điều 46. Nhiệm vụ, quyền hạn và trách nhiệm của Hội thẩm\r\n1. Hội thẩm được phân công xét xử sơ thẩm vụ án hình sự có những nhiệm vụ, quyền hạn:\r\na) Nghiên cứu hồ sơ vụ án trước khi mở phiên tòa;\r\nb) Tiến hành xét xử vụ án;\r\nc) Tiến hành hoạt động tố tụng và biểu quyết những vấn đề thuộc thẩm quyền của Hội đồng xét xử.\r\n2. Hội thẩm phải chịu trách nhiệm trước pháp luật về hành vi, quyết định của mình.', 'tt46', '2024-05-02 22:45:27', '2024-05-02 22:45:27'),
(47, 'Điều 47. Nhiệm vụ, quyền hạn và trách nhiệm của Thư ký Tòa án\r\n1. Thư ký Tòa án được phân công tiến hành tố tụng đối với vụ án hình sự có những nhiệm vụ, quyền hạn:\r\na) Kiểm tra sự có mặt của những người được Tòa án triệu tập; nếu có người vắng mặt thì phải nêu lý do;\r\nb) Phổ biến nội quy phiên tòa;\r\nc) Báo cáo Hội đồng xét xử danh sách những người được triệu tập đến phiên tòa và những người vắng mặt;\r\nd) Ghi biên bản phiên tòa;\r\nđ) Tiến hành hoạt động tố tụng khác thuộc thẩm quyền của Tòa án theo sự phân công của Chánh án Tòa án.\r\n2. Thư ký Tòa án phải chịu trách nhiệm trước pháp luật và trước Chánh án Tòa án về hành vi của mình.', 'tt47', '2024-05-02 22:45:27', '2024-05-02 22:45:27'),
(48, 'Điều 48. Nhiệm vụ, quyền hạn và trách nhiệm của Thẩm tra viên\r\n1. Thẩm tra viên được phân công tiến hành tố tụng đối với vụ án hình sự có những nhiệm vụ, quyền hạn:\r\na) Thẩm tra hồ sơ vụ án mà bản án, quyết định của Tòa án đã có hiệu lực pháp luật theo sự phân công của Chánh án hoặc Phó Chánh án Tòa án;\r\nb) Kết luận việc thẩm tra và báo cáo kết quả thẩm tra với Chánh án Tòa án hoặc Phó Chánh án Tòa án;\r\nc) Thẩm tra viên giúp Chánh án Tòa án thực hiện nhiệm vụ về công tác thi hành án thuộc thẩm quyền của Tòa án và nhiệm vụ khác theo sự phân công của Chánh án Tòa án hoặc Phó Chánh án Tòa án.\r\n2. Thẩm tra viên phải chịu trách nhiệm trước pháp luật và trước Chánh án, Phó Chánh án Tòa án về hành vi của mình.', 'tt48', '2024-05-02 22:46:53', '2024-05-02 22:46:53'),
(49, 'Điều 49. Các trường hợp phải từ chối hoặc thay đổi người có thẩm quyền tiến hành tố tụng\r\nNgười có thẩm quyền tiến hành tố tụng phải từ chối tiến hành tố tụng hoặc bị thay đổi khi thuộc một trong các trường hợp:\r\n1. Đồng thời là bị hại, đương sự; là người đại diện, người thân thích của bị hại, đương sự hoặc của bị can, bị cáo;\r\n2. Đã tham gia với tư cách là người bào chữa, người làm chứng, người giám định, người định giá tài sản, người phiên dịch, người dịch thuật trong vụ án đó;\r\n3. Có căn cứ rõ ràng khác để cho rằng họ có thể không vô tư trong khi làm nhiệm vụ.', 'tt49', '2024-05-02 22:46:53', '2024-05-02 22:46:53'),
(50, 'Điều 50. Người có quyền đề nghị thay đổi người có thẩm quyền tiến hành tố tụng\r\n1. Kiểm sát viên.\r\n2. Người bị tạm giữ, bị can, bị cáo, bị hại, nguyên đơn dân sự, bị đơn dân sự và người đại diện của họ.\r\n3. Người bào chữa, người bảo vệ quyền và lợi ích hợp pháp của bị hại, nguyên đơn dân sự, bị đơn dân sự.', 'tt50', '2024-05-02 22:47:21', '2024-05-02 22:47:21');
INSERT INTO `tbl_chatbot_responses` (`chatbot_responses_id`, `chatbot_responses`, `intent_group_name`, `created_datetime`, `updated_datetime`) VALUES
(1, 'Điều 1. Nhiệm vụ của Bộ luật hình sự\nBộ luật hình sự có nhiệm vụ bảo vệ chủ quyền quốc gia, an ninh của đất nước, bảo vệ chế độ xã hội chủ nghĩa, quyền con người, quyền công dân, bảo vệ quyền bình đẳng giữa đồng bào các dân tộc, bảo vệ lợi ích của Nhà nước, tổ chức, bảo vệ trật tự pháp luật, chống mọi hành vi phạm tội; giáo dục mọi người ý thức tuân theo pháp luật, phòng ngừa và đấu tranh chống tội phạm.\nBộ luật này quy định về tội phạm và hình phạt.', 'law_1', '2024-05-01 01:47:04', '2024-05-01 23:34:21'),
(2, 'Điều 2. Cơ sở của trách nhiệm hình sự\r\n1. Chỉ người nào phạm một tội đã được Bộ luật hình sự quy định mới phải chịu trách nhiệm hình sự.\r\n2. Chỉ pháp nhân thương mại nào phạm một tội đã được quy định tại Điều 76 của Bộ luật này mới phải chịu trách nhiệm hình sự.\r\n', 'law_2', '2024-05-01 12:24:00', '2024-05-01 23:34:24'),
(3, 'Điều 3. Nguyên tắc xử lý\r\n1. Đối với người phạm tội:\r\na) Mọi hành vi phạm tội do người thực hiện phải được phát hiện kịp thời, xử lý nhanh chóng, công minh theo đúng pháp luật;\r\nb) Mọi người phạm tội đều bình đẳng trước pháp luật, không phân biệt giới tính, dân tộc, tín ngưỡng, tôn giáo, thành phần, địa vị xã hội;\r\nc) Nghiêm trị người chủ mưu, cầm đầu, chỉ huy, ngoan cố chống đối, côn đồ, tái phạm nguy hiểm, lợi dụng chức vụ, quyền hạn để phạm tội;\r\nd) Nghiêm trị người phạm tội dùng thủ đoạn xảo quyệt, có tổ chức, có tính chất chuyên nghiệp, cố ý gây hậu quả đặc biệt nghiêm trọng. \r\nKhoan hồng đối với người tự thú, đầu thú, thành khẩn khai báo, tố giác đồng phạm, lập công chuộc tội, tích cực hợp tác với cơ quan có trách nhiệm trong việc phát hiện tội phạm hoặc trong quá trình giải quyết vụ án, ăn năn hối cải, tự nguyện sửa chữa hoặc bồi thường thiệt hại gây ra;\r\nđ) Đối với người lần đầu phạm tội ít nghiêm trọng, thì có thể áp dụng hình phạt nhẹ hơn hình phạt tù, giao họ cho cơ quan, tổ chức hoặc gia đình giám sát, giáo dục;\r\ne) Đối với người bị phạt tù thì buộc họ phải chấp hành hình phạt tại các cơ sở giam giữ, phải lao động, học tập để trở thành người có ích cho xã hội; nếu họ có đủ điều kiện do Bộ luật này quy định, thì có thể được xét giảm thời hạn chấp hành hình phạt, tha tù trước thời hạn có điều kiện;\r\ng) Người đã chấp hành xong hình phạt được tạo điều kiện làm ăn, sinh sống lương thiện, hòa nhập với cộng đồng, khi có đủ điều kiện do luật định thì được xóa án tích.\r\n2. Đối với pháp nhân thương mại phạm tội:\r\na) Mọi hành vi phạm tội do pháp nhân thương mại thực hiện phải được phát hiện kịp thời, xử lý nhanh chóng, công minh theo đúng pháp luật;\r\nb) Mọi pháp nhân thương mại phạm tội đều bình đẳng trước pháp luật, không phân biệt hình thức sở hữu và thành phần kinh tế;\r\nc) Nghiêm trị pháp nhân thương mại phạm tội dùng thủ đoạn tinh vi, có tính chất chuyên nghiệp, cố ý gây hậu quả đặc biệt nghiêm trọng;\r\nd) Khoan hồng đối với pháp nhân thương mại tích cực hợp tác với cơ quan có trách nhiệm trong việc phát hiện tội phạm hoặc trong quá trình giải quyết vụ án, tự nguyện sửa chữa, bồi thường thiệt hại gây ra, chủ động ngăn chặn hoặc khắc phục hậu quả xảy ra.', 'law_3', '2024-05-01 12:24:00', '2024-05-02 22:56:55'),
(4, 'Điều 4. Trách nhiệm phòng ngừa và đấu tranh chống tội phạm\r\n1. Cơ quan Công an, Viện kiểm sát nhân dân, Tòa án nhân dân và các cơ quan hữu quan khác có trách nhiệm thực hiện đầy đủ chức năng, nhiệm vụ, quyền hạn của mình, đồng thời hướng dẫn, giúp đỡ các cơ quan khác của Nhà nước, tổ chức, cá nhân phòng ngừa và đấu tranh chống tội phạm, giám sát và giáo dục người phạm tội tại cộng đồng.\r\n2. Cơ quan, tổ chức có nhiệm vụ giáo dục những người thuộc quyền quản lý của mình nâng cao cảnh giác, ý thức bảo vệ và tuân theo pháp luật, tôn trọng các quy tắc của cuộc sống xã hội chủ nghĩa; kịp thời có biện pháp loại trừ nguyên nhân và điều kiện gây ra tội phạm trong cơ quan, tổ chức của mình.\r\n3. Mọi công dân có nghĩa vụ tích cực tham gia phòng, chống tội phạm.', 'law_4', '2024-05-01 12:37:18', '2024-05-01 23:34:30'),
(5, 'Điều 5. Hiệu lực của Bộ luật hình sự đối với những hành vi phạm tội trên lãnh thổ nước Cộng hòa xã hội chủ nghĩa Việt Nam\r\n1. Bộ luật hình sự được áp dụng đối với mọi hành vi phạm tội thực hiện trên lãnh thổ nước Cộng hòa xã hội chủ nghĩa Việt Nam.\r\nQuy định này cũng được áp dụng đối với hành vi phạm tội hoặc hậu quả của hành vi phạm tội xảy ra trên tàu bay, tàu biển mang quốc tịch Việt Nam hoặc tại vùng đặc quyền kinh tế, thềm lục địa của Việt Nam.\r\n2. Đối với người nước ngoài phạm tội trên lãnh thổ nước Cộng hòa xã hội chủ nghĩa Việt Nam thuộc đối tượng được hưởng quyền miễn trừ ngoại giao hoặc lãnh sự theo pháp luật Việt Nam, theo điều ước quốc tế mà Cộng hòa xã hội chủ nghĩa Việt Nam là thành viên hoặc theo tập quán quốc tế, thì vấn đề trách nhiệm hình sự của họ được giải quyết theo quy định của điều ước quốc tế hoặc theo tập quán quốc tế đó; trường hợp điều ước quốc tế đó không quy định hoặc không có tập quán quốc tế thì trách nhiệm hình sự của họ được giải quyết bằng con đường ngoại giao.', 'law_5', '2024-05-01 12:37:18', '2024-05-01 23:34:33'),
(6, 'Điều 6. Hiệu lực của Bộ luật hình sự đối với những hành vi phạm tội ở ngoài lãnh thổ nước Cộng hòa xã hội chủ nghĩa Việt Nam\r\n1. Công dân Việt Nam hoặc pháp nhân thương mại Việt Nam có hành vi phạm tội ở ngoài lãnh thổ nước Cộng hòa xã hội chủ nghĩa Việt Nam mà Bộ luật này quy định là tội phạm, thì có thể bị truy cứu trách nhiệm hình sự tại Việt Nam theo quy định của Bộ luật này.\r\nQuy định này cũng được áp dụng đối với người không quốc tịch thường trú ở Việt Nam.\r\n2. Người nước ngoài, pháp nhân thương mại nước ngoài phạm tội ở ngoài lãnh thổ nước Cộng hòa xã hội chủ nghĩa Việt Nam có thể bị truy cứu trách nhiệm hình sự theo quy định của Bộ luật này trong trường hợp hành vi phạm tội xâm hại quyền, lợi ích hợp pháp của công dân Việt Nam hoặc xâm hại lợi ích của nước Cộng hòa xã hội chủ nghĩa Việt Nam hoặc theo quy định của điều ước quốc tế mà Cộng hòa xã hội chủ nghĩa Việt Nam là thành viên.\r\n3. Đối với hành vi phạm tội hoặc hậu quả của hành vi phạm tội xảy ra trên tàu bay, tàu biển không mang quốc tịch Việt Nam đang ở tại biển cả hoặc tại giới hạn vùng trời nằm ngoài lãnh thổ nước Cộng hòa xã hội chủ nghĩa Việt Nam, thì người phạm tội có thể bị truy cứu trách nhiệm hình sự theo quy định của Bộ luật này trong trường hợp điều ước quốc tế mà Cộng hòa xã hội chủ nghĩa Việt Nam là thành viên có quy định.', 'law_6', '2024-05-01 12:38:04', '2024-05-01 23:34:37'),
(7, 'Điều 7. Hiệu lực của Bộ luật hình sự về thời gian\r\n1. Điều luật được áp dụng đối với một hành vi phạm tội là điều luật đang có hiệu lực thi hành tại thời điểm mà hành vi phạm tội được thực hiện.\r\n2. Điều luật quy định một tội phạm mới, một hình phạt nặng hơn, một tình tiết tăng nặng mới hoặc hạn chế phạm vi áp dụng án treo, miễn trách nhiệm hình sự, loại trừ trách nhiệm hình sự, miễn hình phạt, giảm hình phạt, xóa án tích và quy định khác không có lợi cho người phạm tội, thì không được áp dụng đối với hành vi phạm tội đã thực hiện trước khi điều luật đó có hiệu lực thi hành.\r\n3. Điều luật xóa bỏ một tội phạm, một hình phạt, một tình tiết tăng nặng, quy định một hình phạt nhẹ hơn, một tình tiết giảm nhẹ mới hoặc mở rộng phạm vi áp dụng án treo, miễn trách nhiệm hình sự, loại trừ trách nhiệm hình sự, miễn hình phạt, giảm hình phạt, tha tù trước thời hạn có điều kiện, xóa án tích và quy định khác có lợi cho người phạm tội, thì được áp dụng đối với hành vi phạm tội đã thực hiện trước khi điều luật đó có hiệu lực thi hành.', 'law_7', '2024-05-01 12:38:04', '2024-05-01 23:34:39'),
(8, 'Điều 8. Khái niệm tội phạm\r\n1. Tội phạm là hành vi nguy hiểm cho xã hội được quy định trong Bộ luật hình sự, do người có năng lực trách nhiệm hình sự hoặc pháp nhân thương mại thực hiện một cách cố ý hoặc vô ý, xâm phạm độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ Tổ quốc, xâm phạm chế độ chính trị, chế độ kinh tế, nền văn hóa, quốc phòng, an ninh, trật tự, an toàn xã hội, quyền, lợi ích hợp pháp của tổ chức, xâm phạm quyền con người, quyền, lợi ích hợp pháp của công dân, xâm phạm những lĩnh vực khác của trật tự pháp luật xã hội chủ nghĩa mà theo quy định của Bộ luật này phải bị xử lý hình sự.\r\n2. Những hành vi tuy có dấu hiệu của tội phạm nhưng tính chất nguy hiểm cho xã hội không đáng kể thì không phải là tội phạm và được xử lý bằng các biện pháp khác.', 'law_8', '2024-05-01 12:38:35', '2024-05-01 23:34:43'),
(9, 'Điều 9. Phân loại tội phạm\r\n1. Căn cứ vào tính chất và mức độ nguy hiểm cho xã hội của hành vi phạm tội được quy định trong Bộ luật này, tội phạm được phân thành 04 loại sau đây:\r\na) Tội phạm ít nghiêm trọng là tội phạm có tính chất và mức độ nguy hiểm cho xã hội không lớn mà mức cao nhất của khung hình phạt do Bộ luật này quy định đối với tội ấy là phạt tiền, phạt cải tạo không giam giữ hoặc phạt tù đến 03 năm;\r\nb) Tội phạm nghiêm trọng là tội phạm có tính chất và mức độ nguy hiểm cho xã hội lớn mà mức cao nhất của khung hình phạt do Bộ luật này quy định đối với tội ấy là từ trên 03 năm tù đến 07 năm tù;\r\nc) Tội phạm rất nghiêm trọng là tội phạm có tính chất và mức độ nguy hiểm cho xã hội rất lớn mà mức cao nhất của khung hình phạt do Bộ luật này quy định đối với tội ấy là từ trên 07 năm tù đến 15 năm tù;\r\nd) Tội phạm đặc biệt nghiêm trọng là tội phạm có tính chất và mức độ nguy hiểm cho xã hội đặc biệt lớn mà mức cao nhất của khung hình phạt do Bộ luật này quy định đối với tội ấy là từ trên 15 năm tù đến 20 năm tù, tù chung thân hoặc tử hình.\r\n2. Tội phạm do pháp nhân thương mại thực hiện được phân loại căn cứ vào tính chất và mức độ nguy hiểm cho xã hội của hành vi phạm tội theo quy định tại khoản 1 Điều này và quy định tương ứng đối với các tội phạm được quy định tại Điều 76 của Bộ luật này.', 'law_9', '2024-05-01 12:38:35', '2024-05-02 22:59:33'),
(10, 'Điều 10. Cố ý phạm tội\r\nCố ý phạm tội là phạm tội trong những trường hợp sau đây:\r\n1. Người phạm tội nhận thức rõ hành vi của mình là nguy hiểm cho xã hội, thấy trước hậu quả của hành vi đó và mong muốn hậu quả xảy ra;\r\n2. Người phạm tội nhận thức rõ hành vi của mình là nguy hiểm cho xã hội, thấy trước hậu quả của hành vi đó có thể xảy ra, tuy không mong muốn nhưng vẫn có ý thức để mặc cho hậu quả xảy ra.', 'law_10', '2024-05-01 12:39:01', '2024-05-01 23:34:56'),
(11, 'Điều 11. Vô ý phạm tội\r\nVô ý phạm tội là phạm tội trong những trường hợp sau đây:\r\n1. Người phạm tội tuy thấy trước hành vi của mình có thể gây ra hậu quả nguy hại cho xã hội nhưng cho rằng hậu quả đó sẽ không xảy ra hoặc có thể ngăn ngừa được;\r\n2. Người phạm tội không thấy trước hành vi của mình có thể gây ra hậu quả nguy hại cho xã hội, mặc dù phải thấy trước và có thể thấy trước hậu quả đó.', 'law_11', '2024-05-01 23:30:32', '2024-05-01 23:35:00'),
(12, 'Điều 12. Tuổi chịu trách nhiệm hình sự\r\n1. Người từ đủ 16 tuổi trở lên phải chịu trách nhiệm hình sự về mọi tội phạm, trừ những tội phạm mà Bộ luật này có quy định khác.\r\n2. Người từ đủ 14 tuổi trở lên, nhưng chưa đủ 16 tuổi chỉ phải chịu trách nhiệm hình sự về tội giết người, tội cố ý gây thương tích hoặc gây tổn hại cho sức khỏe của người khác, tội hiếp dâm, tội hiếp dâm người dưới 16 tuổi, tội cưỡng dâm người từ đủ 13 tuổi đến dưới 16 tuổi, tội cướp tài sản, tội bắt cóc nhằm chiếm đoạt tài sản; về tội phạm rất nghiêm trọng, tội phạm đặc biệt nghiêm trọng quy định tại một trong các điều sau đây:\r\na) Điều 143 (tội cưỡng dâm); Điều 150 (tội mua bán người); Điều 151 (tội mua bán người dưới 16 tuổi);\r\nb) Điều 170 (tội cưỡng đoạt tài sản); Điều 171 (tội cướp giật tài sản); Điều 173 (tội trộm cắp tài sản); Điều 178 (tội hủy hoại hoặc cố ý làm hư hỏng tài sản);\r\nc) Điều 248 (tội sản xuất trái phép chất ma túy); Điều 249 (tội tàng trữ trái phép chất ma túy); Điều 250 (tội vận chuyển trái phép chất ma túy); Điều 251 (tội mua bán trái phép chất ma túy); Điều 252 (tội chiếm đoạt chất ma túy);\r\nd) Điều 265 (tội tổ chức đua xe trái phép); Điều 266 (tội đua xe trái phép);\r\nđ) Điều 285 (tội sản xuất, mua bán, công cụ, thiết bị, phần mềm để sử dụng vào mục đích trái pháp luật); Điều 286 (tội phát tán chương trình tin học gây hại cho hoạt động của mạng máy tính, mạng viễn thông, phương tiện điện tử); Điều 287 (tội cản trở hoặc gây rối loạn hoạt động của mạng máy tính, mạng viễn thông, phương tiện điện tử); Điều 289 (tội xâm nhập trái phép vào mạng máy tính, mạng viễn thông hoặc phương tiện điện tử của người khác); Điều 290 (tội sử dụng mạng máy tính, mạng viễn thông, phương tiện điện tử thực hiện hành vi chiếm đoạt tài sản);\r\ne) Điều 299 (tội khủng bố); Điều 303 (tội phá hủy công trình, cơ sở, phương tiện quan trọng về an ninh quốc gia); Điều 304 (tội chế tạo, tàng trữ, vận chuyển, sử dụng, mua bán trái phép hoặc chiếm đoạt vũ khí quân dụng, phương tiện kỹ thuật quân sự).', 'law_12', '2024-05-01 23:30:32', '2024-05-01 23:35:04'),
(13, 'Điều 13. Phạm tội do dùng rượu, bia hoặc chất kích thích mạnh khác\r\nNgười phạm tội trong tình trạng mất khả năng nhận thức hoặc khả năng điều khiển hành vi của mình do dùng rượu, bia hoặc chất kích thích mạnh khác, thì vẫn phải chịu trách nhiệm hình sự.', 'law_13', '2024-05-01 23:30:50', '2024-05-01 23:35:06'),
(14, 'Điều 14. Chuẩn bị phạm tội\r\n1. Chuẩn bị phạm tội là tìm kiếm, sửa soạn công cụ, phương tiện hoặc tạo ra những điều kiện khác để thực hiện tội phạm hoặc thành lập, tham gia nhóm tội phạm trừ trường hợp quy định tại Điều 109, điểm a khoản 2 Điều 113 hoặc điểm a khoản 2 Điều 299 của Bộ luật này.\r\n2. Người chuẩn bị phạm một trong các tội sau đây thì phải chịu trách nhiệm hình sự:\r\na) Điều 108 (tội phản bội Tổ quốc); Điều 110 (tội gián điệp); Điều 111 (tội xâm phạm an ninh lãnh thổ); Điều 112 (tội bạo loạn); Điều 113 (tội khủng bố nhằm chống chính quyền nhân dân); Điều 114 (tội phá hoại cơ sở vật chất – kỹ thuật của nước cộng hòa xã hội chủ nghĩa Việt Nam); Điều 117 (tội làm, tàng trữ, phát tán hoặc tuyên truyền thông tin, tài liệu, vật phẩm nhằm chống Nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam); Điều 118 (tội phá rối an ninh); Điều 119 (tội chống phá trại giam); Điều 120 (tội tổ chức, cưỡng ép, xúi giục người khác trốn đi nước ngoài hoặc trốn ở lại nước ngoài nhằm chống chính quyền nhân dân); Điều 121 (tội trốn đi nước ngoài hoặc trốn ở lại nước ngoài nhằm chống chính quyền nhân dân);\r\nb) Điều 123 (tội giết người); Điều 134 (tội cố ý gây thương tích hoặc gây tổn hại cho sức khỏe của người khác);\r\nc) Điều 168 (tội cướp tài sản); Điều 169 (tội bắt cóc nhằm chiếm đoạt tài sản);\r\nd) Điều 299 (tội khủng bố); Điều 300 (tội tài trợ khủng bố); Điều 301 (tội bắt cóc con tin); Điều 302 (tội cướp biển); Điều 303 (tội phá hủy công trình, cơ sở, phương tiện quan trọng về an ninh quốc gia); Điều 324 (tội rửa tiền).\r\n3. Người từ đủ 14 đến dưới 16 tuổi chuẩn bị phạm tội quy định tại điểm b và điểm c khoản 2 Điều này thì phải chịu trách nhiệm hình sự.', 'law_14', '2024-05-01 23:38:07', '2024-05-01 23:38:24'),
(15, 'Điều 15. Phạm tội chưa đạt\r\nPhạm tội chưa đạt là cố ý thực hiện tội phạm nhưng không thực hiện được đến cùng vì những nguyên nhân ngoài ý muốn của người phạm tội.\r\nNgười phạm tội chưa đạt phải chịu trách nhiệm hình sự về tội phạm chưa đạt.', 'law_15', '2024-05-01 23:38:07', '2024-05-01 23:38:28'),
(16, 'Điều 16. Tự ý nửa chừng chấm dứt việc phạm tội\r\nTự ý nửa chừng chấm dứt việc phạm tội là tự mình không thực hiện tội phạm đến cùng, tuy không có gì ngăn cản.\r\nNgười tự ý nửa chừng chấm dứt việc phạm tội được miễn trách nhiệm hình sự về tội định phạm; nếu hành vi thực tế đã thực hiện có đủ yếu tố cấu thành của một tội khác, thì người đó phải chịu trách nhiệm hình sự về tội này.', 'law_16', '2024-05-02 00:08:37', '2024-05-02 00:08:37'),
(17, 'Điều 17. Đồng phạm\r\n1. Đồng phạm là trường hợp có hai người trở lên cố ý cùng thực hiện một tội phạm.\r\n2. Phạm tội có tổ chức là hình thức đồng phạm có sự câu kết chặt chẽ giữa những người cùng thực hiện tội phạm.\r\n3. Người đồng phạm bao gồm người tổ chức, người thực hành, người xúi giục, người giúp sức.\r\nNgười thực hành là người trực tiếp thực hiện tội phạm.\r\nNgười tổ chức là người chủ mưu, cầm đầu, chỉ huy việc thực hiện tội phạm.\r\nNgười xúi giục là người kích động, dụ dỗ, thúc đẩy người khác thực hiện tội phạm.\r\nNgười giúp sức là người tạo điều kiện tinh thần hoặc vật chất cho việc thực hiện tội phạm.\r\n4. Người đồng phạm không phải chịu trách nhiệm hình sự về hành vi vượt quá của người thực hành.', 'law_17', '2024-05-02 00:08:37', '2024-05-02 00:08:37'),
(18, 'Điều 18. Che giấu tội phạm\r\n1. Người nào không hứa hẹn trước, nhưng sau khi biết tội phạm được thực hiện đã che giấu người phạm tội, dấu vết, tang vật của tội phạm hoặc có hành vi khác cản trở việc phát hiện, điều tra, xử lý người phạm tội, thì phải chịu trách nhiệm hình sự về tội che giấu tội phạm trong những trường hợp mà Bộ luật này quy định.\r\n2. Người che giấu tội phạm là ông, bà, cha, mẹ, con, cháu, anh chị em ruột, vợ hoặc chồng của người phạm tội không phải chịu trách nhiệm hình sự theo quy định tại khoản 1 Điều này, trừ trường hợp che giấu các tội xâm phạm an ninh quốc gia hoặc tội đặc biệt nghiêm trọng khác quy định tại Điều 389 của Bộ luật này.', 'law_18', '2024-05-02 00:12:31', '2024-05-02 00:12:31'),
(19, 'Điều 19. Không tố giác tội phạm\r\n1. Người nào biết rõ tội phạm đang được chuẩn bị, đang được thực hiện hoặc đã được thực hiện mà không tố giác, thì phải chịu trách nhiệm hình sự về tội không tố giác tội phạm trong những trường hợp quy định tại Điều 389 của Bộ luật này.\r\n2. Người không tố giác là ông, bà, cha, mẹ, con, cháu, anh chị em ruột, vợ hoặc chồng của người phạm tội không phải chịu trách nhiệm theo quy định tại khoản 1 Điều này, trừ trường hợp không tố giác các tội xâm phạm an ninh quốc gia hoặc tội đặc biệt nghiêm trọng khác quy định tại Điều 389 của Bộ luật này.\r\n3. Người bào chữa không phải chịu trách nhiệm hình sự theo quy ðịnh tại khoản 1 Ðiều này trong trường hợp không tố giác tội phạm do chính người mà mình bào chữa đã thực hiện hoặc đã tham gia thực hiện mà người bào chữa biết được khi thực hiện nhiệm vụ bào chữa, trừ trường hợp không tố giác các tội xâm phạm an ninh quốc gia hoặc tội phạm đặc biệt nghiêm trọng khác quy định tại Điều 389 của Bộ luật này.', 'law_19', '2024-05-02 00:12:31', '2024-05-02 00:12:31'),
(20, 'Điều 20. Sự kiện bất ngờ\r\nNgười thực hiện hành vi gây hậu quả nguy hại cho xã hội trong trường hợp không thể thấy trước hoặc không buộc phải thấy trước hậu quả của hành vi đó, thì không phải chịu trách nhiệm hình sự.', 'law_20', '2024-05-02 00:39:23', '2024-05-02 00:39:23'),
(21, 'Điều 21. Tình trạng không có năng lực trách nhiệm hình sự\r\nNgười thực hiện hành vi nguy hiểm cho xã hội trong khi đang mắc bệnh tâm thần, một bệnh khác làm mất khả năng nhận thức hoặc khả năng điều khiển hành vi của mình, thì không phải chịu trách nhiệm hình sự.', 'law_21', '2024-05-02 00:39:23', '2024-05-02 00:39:23'),
(22, 'Điều 22. Phòng vệ chính đáng\r\n1. Phòng vệ chính đáng là hành vi của người vì bảo vệ quyền hoặc lợi ích chính đáng của mình, của người khác hoặc lợi ích của Nhà nước, của cơ quan, tổ chức mà chống trả lại một cách cần thiết người đang có hành vi xâm phạm các lợi ích nói trên.\r\nPhòng vệ chính đáng không phải là tội phạm.\r\n2. Vượt quá giới hạn phòng vệ chính đáng là hành vi chống trả rõ ràng quá mức cần thiết, không phù hợp với tính chất và mức độ nguy hiểm cho xã hội của hành vi xâm hại.\r\nNgười có hành vi vượt quá giới hạn phòng vệ chính đáng phải chịu trách nhiệm hình sự theo quy định của Bộ luật này.', 'law_22', '2024-05-02 00:48:00', '2024-05-02 00:48:00'),
(23, 'Điều 23. Tình thế cấp thiết\r\n1. Tình thế cấp thiết là tình thế của người vì muốn tránh gây thiệt hại cho quyền, lợi ích hợp pháp của mình, của người khác hoặc lợi ích của Nhà nước, của cơ quan, tổ chức mà không còn cách nào khác là phải gây một thiệt hại nhỏ hơn thiệt hại cần ngăn ngừa.\r\nHành vi gây thiệt hại trong tình thế cấp thiết không phải là tội phạm.\r\n2. Trong trường hợp thiệt hại gây ra rõ ràng vượt quá yêu cầu của tình thế cấp thiết, thì người gây thiệt hại đó phải chịu trách nhiệm hình sự.', 'law_23', '2024-05-02 00:48:00', '2024-05-02 00:48:00'),
(24, 'Điều 24. Gây thiệt hại trong khi bắt giữ người phạm tội\r\n1. Hành vi của người để bắt giữ người thực hiện hành vi phạm tội mà không còn cách nào khác là buộc phải sử dụng vũ lực cần thiết gây thiệt hại cho người bị bắt giữ thì không phải là tội phạm.\r\n2. Trường hợp gây thiệt hại do sử dụng vũ lực rõ ràng vượt quá mức cần thiết, thì người gây thiệt hại phải chịu trách nhiệm hình sự.', 'law_24', '2024-05-02 11:12:25', '2024-05-02 11:12:25'),
(25, 'Điều 25. Rủi ro trong nghiên cứu, thử nghiệm, áp dụng tiến bộ khoa học, kỹ thuật và công nghệ\r\nHành vi gây ra thiệt hại trong khi thực hiện việc nghiên cứu, thử nghiệm, áp dụng tiến bộ khoa học, kỹ thuật và công nghệ mới mặc dù đã tuân thủ đúng quy trình, quy phạm, áp dụng đầy đủ biện pháp phòng ngừa thì không phải là tội phạm.\r\nNgười nào không áp dụng đúng quy trình, quy phạm, không áp dụng đầy đủ biện pháp phòng ngừa mà gây thiệt hại thì vẫn phải chịu trách nhiệm hình sự.', 'law_25', '2024-05-02 11:12:25', '2024-05-02 11:12:25'),
(26, 'Điều 26. Thi hành mệnh lệnh của người chỉ huy hoặc của cấp trên\nNgười thực hiện hành vi gây thiệt hại trong khi thi hành mệnh lệnh của người chỉ huy hoặc của cấp trên trong lực lượng vũ trang nhân dân để thực hiện nhiệm vụ quốc phòng, an ninh nếu đã thực hiện đầy đủ quy trình báo cáo người ra mệnh lệnh nhưng người ra mệnh lệnh vẫn yêu cầu chấp hành mệnh lệnh đó, thì không phải chịu trách nhiệm hình sự. Trong trường hợp này người ra mệnh lệnh phải chịu trách nhiệm hình sự.\nQuy định này không áp dụng đối với các trường hợp quy định tại khoản 2 Điều 421, khoản 2 Điều 422 và khoản 2 Điều 423 của Bộ luật này.', 'law_26', '2024-05-02 11:15:01', '2024-05-02 11:37:54'),
(27, 'Điều 27. Thời hiệu truy cứu trách nhiệm hình sự\r\n1. Thời hiệu truy cứu trách nhiệm hình sự là thời hạn do Bộ luật này quy định mà khi hết thời hạn đó thì người phạm tội không bị truy cứu trách nhiệm hình sự.\r\n2. Thời hiệu truy cứu trách nhiệm hình sự được quy định như sau:\r\na) 05 năm đối với tội phạm ít nghiêm trọng;\r\nb) 10 năm đối với tội phạm nghiêm trọng;\r\nc) 15 năm đối với tội phạm rất nghiêm trọng;\r\nd) 20 năm đối với tội phạm đặc biệt nghiêm trọng.\r\n3. Thời hiệu truy cứu trách nhiệm hình sự được tính từ ngày tội phạm được thực hiện. Nếu trong thời hạn quy định tại khoản 2 Điều này, người phạm tội lại thực hiện hành vi phạm tội mới mà Bộ luật này quy định mức cao nhất của khung hình phạt đối với tội ấy trên 01 năm tù, thì thời hiệu đối với tội cũ được tính lại kể từ ngày thực hiện hành vi phạm tội mới.\r\nNếu trong thời hạn quy định tại khoản 2 Điều này, người phạm tội cố tình trốn tránh và đã có quyết định truy nã, thì thời hiệu tính lại kể từ khi người đó ra đầu thú hoặc bị bắt giữ.', 'law_27', '2024-05-02 11:15:01', '2024-05-02 11:38:14'),
(28, 'Điều 28. Không áp dụng thời hiệu truy cứu trách nhiệm hình sự\r\nKhông áp dụng thời hiệu truy cứu trách nhiệm hình sự quy định tại Điều 27 của Bộ luật này đối với các tội phạm sau đây:\r\n1. Các tội xâm phạm an ninh quốc gia quy định tại Chương XIII của Bộ luật này;\r\n2. Các tội phá hoại hòa bình, chống loài người và tội phạm chiến tranh quy định tại Chương XXVI của Bộ luật này;\r\n3. Tội tham ô tài sản thuộc trường hợp quy định tại khoản 3 và khoản 4 Điều 353 của Bộ luật này; tội nhận hối lộ thuộc trường hợp quy định tại khoản 3 và khoản 4 Điều 354 của Bộ luật này.', 'law_28', '2024-05-02 11:18:33', '2024-05-02 11:18:33'),
(29, 'Điều 29. Căn cứ miễn trách nhiệm hình sự\r\n1. Người phạm tội được miễn trách nhiệm hình sự khi có một trong những căn cứ sau đây:\r\na) Khi tiến hành điều tra, truy tố hoặc xét xử, do có sự thay đổi chính sách, pháp luật làm cho hành vi phạm tội không còn nguy hiểm cho xã hội nữa;\r\nb) Khi có quyết định đại xá.\r\n2. Người phạm tội có thể được miễn trách nhiệm hình sự khi có một trong các căn cứ sau đây:\r\na) Khi tiến hành điều tra, truy tố, xét xử do chuyển biến của tình hình mà người phạm tội không còn nguy hiểm cho xã hội nữa;\r\nb) Khi tiến hành điều tra, truy tố, xét xử, người phạm tội mắc bệnh hiểm nghèo dẫn đến không còn khả năng gây nguy hiểm cho xã hội nữa;\r\nc) Người phạm tội tự thú, khai rõ sự việc, góp phần có hiệu quả vào việc phát hiện và điều tra tội phạm, cố gắng hạn chế đến mức thấp nhất hậu quả của tội phạm và lập công lớn hoặc có cống hiến đặc biệt, được Nhà nước và xã hội thừa nhận.\r\n3. Người thực hiện tội phạm ít nghiêm trọng hoặc tội phạm nghiêm trọng do vô ý gây thiệt hại về tính mạng, sức khỏe, danh dự, nhân phẩm hoặc tài sản của người khác và được người bị hại hoặc người đại diện của người bị hại tự nguyện hòa giải và đề nghị miễn trách nhiệm hình sự, thì có thể được miễn trách nhiệm hình sự.\r\n', 'law_29', '2024-05-02 11:37:41', '2024-05-02 11:37:41'),
(30, 'Điều 30. Khái niệm hình phạt\r\nHình phạt là biện pháp cưỡng chế nghiêm khắc nhất của Nhà nước được quy định trong Bộ luật này, do Tòa án quyết định áp dụng đối với người hoặc pháp nhân thương mại phạm tội nhằm tước bỏ hoặc hạn chế quyền, lợi ích của người, pháp nhân thương mại đó.', 'law_30', '2024-05-02 11:37:41', '2024-05-02 11:37:41'),
(31, 'Điều 31. Mục đích của hình phạt\r\nHình phạt không chỉ nhằm trừng trị người, pháp nhân thương mại phạm tội mà còn giáo dục họ ý thức tuân theo pháp luật và các quy tắc của cuộc sống, ngăn ngừa họ phạm tội mới; giáo dục người, pháp nhân thương mại khác tôn trọng pháp luật, phòng ngừa và đấu tranh chống tội phạm.', 'law_31', '2024-05-02 11:42:29', '2024-05-02 11:42:29'),
(32, 'Điều 32. Các hình phạt đối với người phạm tội\r\n1. Hình phạt chính bao gồm:\r\na) Cảnh cáo;\r\nb) Phạt tiền;\r\nc) Cải tạo không giam giữ;\r\nd) Trục xuất;\r\nđ) Tù có thời hạn;\r\ne) Tù chung thân;\r\ng) Tử hình.\r\n2. Hình phạt bổ sung bao gồm:\r\na) Cấm đảm nhiệm chức vụ, cấm hành nghề hoặc làm công việc nhất định;\r\nb) Cấm cư trú;\r\nc) Quản chế;\r\nd) Tước một số quyền công dân;\r\nđ) Tịch thu tài sản;\r\ne) Phạt tiền, khi không áp dụng là hình phạt chính;\r\ng) Trục xuất, khi không áp dụng là hình phạt chính.\r\n3. Đối với mỗi tội phạm, người phạm tội chỉ bị áp dụng một hình phạt chính và có thể bị áp dụng một hoặc một số hình phạt bổ sung.', 'law_32', '2024-05-02 11:42:29', '2024-05-02 11:42:29'),
(33, 'Điều 33. Các hình phạt đối với pháp nhân thương mại phạm tội\r\n1. Hình phạt chính bao gồm:\r\na) Phạt tiền;\r\nb) Đình chỉ hoạt động có thời hạn;\r\nc) Đình chỉ hoạt động vĩnh viễn.\r\n2. Hình phạt bổ sung bao gồm:\r\na) Cấm kinh doanh, cấm hoạt động trong một số lĩnh vực nhất định;\r\nb) Cấm huy động vốn;\r\nc) Phạt tiền, khi không áp dụng là hình phạt chính.\r\n3. Đối với mỗi tội phạm, pháp nhân thương mại phạm tội chỉ bị áp dụng một hình phạt chính và có thể bị áp dụng một hoặc một số hình phạt bổ sung.', 'law_33', '2024-05-02 11:43:06', '2024-05-02 11:43:06'),
(34, 'Điều 34. Cảnh cáo\r\nCảnh cáo được áp dụng đối với người phạm tội ít nghiêm trọng và có nhiều tình tiết giảm nhẹ, nhưng chưa đến mức miễn hình phạt.', 'law_34', '2024-05-02 11:43:06', '2024-05-02 11:43:06'),
(35, 'Điều 35. Phạt tiền\r\n1. Phạt tiền được áp dụng là hình phạt chính đối với các trường hợp sau đây:\r\na) Người phạm tội ít nghiêm trọng, phạm tội nghiêm trọng do Bộ luật này quy định;\r\nb) Người phạm tội rất nghiêm trọng xâm phạm trật tự quản lý kinh tế, môi trường, trật tự công cộng, an toàn công cộng và một số tội phạm khác do Bộ luật này quy định.\r\n2. Hình phạt tiền được áp dụng là hình phạt bổ sung đối với người phạm tội về tham nhũng, ma túy hoặc những tội phạm khác do Bộ luật này quy định.\r\n3. Mức tiền phạt được quyết định căn cứ vào tính chất và mức độ nguy hiểm của tội phạm, đồng thời có xét đến tình hình tài sản của người phạm tội, sự biến động của giá cả, nhưng không được thấp hơn 1.000.000 đồng.\r\n4. Hình phạt tiền đối với pháp nhân thương mại phạm tội được quy định tại Điều 77 của Bộ luật này.\r\n', 'law_35', '2024-05-02 11:45:53', '2024-05-02 11:45:53'),
(36, 'Điều 36. Cải tạo không giam giữ\r\n1. Cải tạo không giam giữ được áp dụng từ 06 tháng đến 03 năm đối với người phạm tội ít nghiêm trọng, phạm tội nghiêm trọng do Bộ luật này quy định mà đang có nơi làm việc ổn định hoặc có nơi cư trú rõ ràng nếu xét thấy không cần thiết phải cách ly người phạm tội khỏi xã hội.\r\nNếu người bị kết án đã bị tạm giữ, tạm giam thì thời gian tạm giữ, tạm giam được trừ vào thời gian chấp hành hình phạt cải tạo không giam giữ, cứ 01 ngày tạm giữ, tạm giam bằng 03 ngày cải tạo không giam giữ.\r\n2. Tòa án giao người bị phạt cải tạo không giam giữ cho cơ quan, tổ chức nơi người đó làm việc, học tập hoặc Ủy ban nhân dân cấp xã nơi người đó cư trú để giám sát, giáo dục. Gia đình người bị kết án có trách nhiệm phối hợp với cơ quan, tổ chức hoặc Ủy ban nhân dân cấp xã trong việc giám sát, giáo dục người đó.\r\n3. Trong thời gian chấp hành án, người bị kết án phải thực hiện một số nghĩa vụ theo các quy định về cải tạo không giam giữ và bị khấu trừ một phần thu nhập từ 05% đến 20% để sung quỹ nhà nước. Việc khấu trừ thu nhập được thực hiện hàng tháng. Trong trường hợp đặc biệt, Tòa án có thể cho miễn việc khấu trừ thu nhập, nhưng phải ghi rõ lý do trong bản án.\r\nKhông khấu trừ thu nhập đối với người chấp hành án là người đang thực hiện nghĩa vụ quân sự.\r\n4. Trường hợp người bị phạt cải tạo không giam giữ không có việc làm hoặc bị mất việc làm trong thời gian chấp hành hình phạt này thì phải thực hiện một số công việc lao động phục vụ cộng đồng trong thời gian cải tạo không giam giữ.\r\nThời gian lao động phục vụ cộng đồng không quá 04 giờ trong một ngày và không quá 05 ngày trong 01 tuần.\r\nKhông áp dụng biện pháp lao động phục vụ cộng đồng đối với phụ nữ có thai hoặc đang nuôi con dưới 06 tháng tuổi, người già yếu, người bị bệnh hiểm nghèo, người khuyết tật nặng hoặc khuyết tật đặc biệt nặng.\r\nNgười bị kết án cải tạo không giam giữ phải thực hiện những nghĩa vụ quy định tại Luật thi hành án hình sự.', 'law_36', '2024-05-02 11:46:54', '2024-05-02 11:46:54'),
(37, 'Điều 37. Trục xuất\r\nTrục xuất là buộc người nước ngoài bị kết án phải rời khỏi lãnh thổ nước Cộng hòa xã hội chủ nghĩa Việt Nam.\r\nTrục xuất được Tòa án áp dụng là hình phạt chính hoặc hình phạt bổ sung trong từng trường hợp cụ thể.', 'law_37', '2024-05-02 11:46:54', '2024-05-02 11:46:54'),
(38, 'Điều 38. Tù có thời hạn\r\n1. Tù có thời hạn là buộc người bị kết án phải chấp hành hình phạt tại cơ sở giam giữ trong một thời hạn nhất định.\r\nTù có thời hạn đối với người phạm một tội có mức tối thiểu là 03 tháng và mức tối đa là 20 năm.\r\nThời gian tạm giữ, tạm giam được trừ vào thời hạn chấp hành hình phạt tù, cứ 01 ngày tạm giữ, tạm giam bằng 01 ngày tù.\r\n2. Không áp dụng hình phạt tù có thời hạn đối với người lần đầu phạm tội ít nghiêm trọng do vô ý và có nơi cư trú rõ ràng.\r\n', 'law_38', '2024-05-02 11:54:15', '2024-05-02 11:54:15'),
(39, 'Điều 39. Tù chung thân\r\nTù chung thân là hình phạt tù không thời hạn được áp dụng đối với người phạm tội đặc biệt nghiêm trọng, nhưng chưa đến mức bị xử phạt tử hình.\r\nKhông áp dụng hình phạt tù chung thân đối với người dưới 18 tuổi phạm tội.', 'law_39', '2024-05-02 11:54:15', '2024-05-02 11:54:15'),
(40, 'Điều 40. Tử hình\r\n1. Tử hình là hình phạt đặc biệt chỉ áp dụng đối với người phạm tội đặc biệt nghiêm trọng thuộc một trong nhóm các tội xâm phạm an ninh quốc gia, xâm phạm tính mạng con người, các tội phạm về ma túy, tham nhũng và một số tội phạm đặc biệt nghiêm trọng khác do Bộ luật này quy định.\r\n2. Không áp dụng hình phạt tử hình đối với người dưới 18 tuổi khi phạm tội, phụ nữ có thai, phụ nữ đang nuôi con dưới 36 tháng tuổi hoặc người đủ 75 tuổi trở lên khi phạm tội hoặc khi xét xử.\r\n3. Không thi hành án tử hình đối với người bị kết án nếu thuộc một trong các trường hợp sau đây:\r\na) Phụ nữ có thai hoặc phụ nữ đang nuôi con dưới 36 tháng tuổi;\r\nb) Người đủ 75 tuổi trở lên;\r\nc) Người bị kết án tử hình về tội tham ô tài sản, tội nhận hối lộ mà sau khi bị kết án đã chủ động nộp lại ít nhất ba phần tư tài sản tham ô, nhận hối lộ và hợp tác tích cực với cơ quan chức năng trong việc phát hiện, điều tra, xử lý tội phạm hoặc lập công lớn.\r\n4. Trong trường hợp quy định tại khoản 3 Điều này hoặc trường hợp người bị kết án tử hình được ân giảm, thì hình phạt tử hình được chuyển thành tù chung thân.', 'law_40', '2024-05-02 11:54:15', '2024-05-02 11:54:15'),
(41, 'Điều 41. Cấm đảm nhiệm chức vụ, cấm hành nghề hoặc làm công việc nhất định\r\nCấm đảm nhiệm chức vụ, cấm hành nghề hoặc làm công việc nhất định được áp dụng khi xét thấy nếu để người bị kết án đảm nhiệm chức vụ, hành nghề hoặc làm công việc đó thì có thể gây nguy hại cho xã hội.\r\nThời hạn cấm là từ 01 năm đến 05 năm, kể từ ngày chấp hành xong hình phạt tù hoặc từ ngày bản án có hiệu lực pháp luật nếu hình phạt chính là cảnh cáo, phạt tiền, cải tạo không giam giữ hoặc trong trường hợp người bị kết án được hưởng án treo.', 'law_41', '2024-05-02 11:54:15', '2024-05-02 11:54:15'),
(42, 'Điều 42. Cấm cư trú\r\nCấm cư trú là buộc người bị kết án phạt tù không được tạm trú hoặc thường trú ở một số địa phương nhất định.\r\nThời hạn cấm cư trú là từ 01 năm đến 05 năm, kể từ ngày chấp hành xong hình phạt tù.', 'law_42', '2024-05-02 11:54:15', '2024-05-02 11:54:15'),
(43, 'Điều 43. Quản chế\r\nQuản chế là buộc người bị kết án phạt tù phải cư trú, làm ăn sinh sống và cải tạo ở một địa phương nhất định dưới sự kiểm soát, giáo dục của chính quyền và nhân dân địa phương. Trong thời gian quản chế, người bị kết án không được tự ý ra khỏi nơi cư trú, bị tước một số quyền công dân theo quy định tại Điều 44 của Bộ luật này và bị cấm hành nghề hoặc làm công việc nhất định.\r\nQuản chế được áp dụng đối với người phạm tội xâm phạm an ninh quốc gia, người tái phạm nguy hiểm hoặc trong những trường hợp khác do Bộ luật này quy định.\r\nThời hạn quản chế là từ 01 năm đến 05 năm, kể từ ngày chấp hành xong hình phạt tù.', 'law_43', '2024-05-02 11:54:15', '2024-05-02 11:54:15'),
(44, 'Điều 44. Tước một số quyền công dân\r\n1. Công dân Việt Nam bị kết án phạt tù về tội xâm phạm an ninh quốc gia hoặc tội phạm khác trong những trường hợp do Bộ luật này quy định, thì bị tước một hoặc một số quyền công dân sau đây:\r\na) Quyền ứng cử đại biểu cơ quan quyền lực Nhà nước;\r\nb) Quyền làm việc trong các cơ quan nhà nước và quyền phục vụ trong lực lượng vũ trang nhân dân.\r\n2. Thời hạn tước một số quyền công dân là từ 01 năm đến 05 năm, kể từ ngày chấp hành xong hình phạt tù hoặc kể từ ngày bản án có hiệu lực pháp luật trong trường hợp người bị kết án được hưởng án treo.', 'law_44', '2024-05-02 11:54:15', '2024-05-02 11:54:15'),
(45, 'Điều 45. Tịch thu tài sản\r\nTịch thu tài sản là tước một phần hoặc toàn bộ tài sản thuộc sở hữu của người bị kết án để nộp vào ngân sách nhà nước.\r\nTịch thu tài sản chỉ được áp dụng đối với người bị kết án về tội phạm nghiêm trọng, tội phạm rất nghiêm trọng hoặc tội phạm đặc biệt nghiêm trọng xâm phạm an ninh quốc gia, tội phạm về ma tuý, tham nhũng hoặc tội phạm khác do Bộ luật này quy định.\r\nKhi tịch thu toàn bộ tài sản vẫn để cho người bị kết án và gia đình họ có điều kiện sinh sống.', 'law_45', '2024-05-02 11:54:15', '2024-05-02 11:54:15'),
(46, 'Điều 46. Các biện pháp tư pháp\r\n1. Biện pháp tư pháp đối với người phạm tội bao gồm:\r\na) Tịch thu vật, tiền trực tiếp liên quan đến tội phạm;\r\nb) Trả lại tài sản, sửa chữa hoặc bồi thường thiệt hại; buộc công khai xin lỗi;\r\nc) Bắt buộc chữa bệnh.\r\n2. Biện pháp tư pháp đối với pháp nhân thương mại phạm tội bao gồm:\r\na) Tịch thu vật, tiền trực tiếp liên quan đến tội phạm;\r\nb) Trả lại tài sản, sửa chữa hoặc bồi thường thiệt hại; buộc công khai xin lỗi;\r\nc) Khôi phục lại tình trạng ban đầu;\r\nd) Thực hiện một số biện pháp nhằm khắc phục, ngăn chặn hậu quả tiếp tục xảy ra.', 'law_46', '2024-05-02 11:54:15', '2024-05-02 11:54:15'),
(47, 'Điều 47. Tịch thu vật, tiền trực tiếp liên quan đến tội phạm\r\n1. Việc tịch thu sung vào ngân sách nhà nước hoặc tịch thu tiêu hủy được áp dụng đối với:\r\na) Công cụ, phương tiện dùng vào việc phạm tội;\r\nb) Vật hoặc tiền do phạm tội hoặc do mua bán, đổi chác những thứ ấy mà có; khoản thu lợi bất chính từ việc phạm tội;\r\nc) Vật thuộc loại Nhà nước cấm lưu hành.\r\n2. Đối với vật, tiền bị người phạm tội chiếm đoạt hoặc sử dụng trái phép, thì không tịch thu mà trả lại cho chủ sở hữu hoặc người quản lý hợp pháp.\r\n3. Vật, tiền là tài sản của người khác, nếu người này có lỗi trong việc để cho người phạm tội sử dụng vào việc thực hiện tội phạm, thì có thể bị tịch thu.', 'law_47', '2024-05-02 11:54:15', '2024-05-02 11:54:15'),
(48, 'Điều 48. Trả lại tài sản, sửa chữa hoặc bồi thường thiệt hại; buộc công khai xin lỗi\r\n1. Người phạm tội phải trả lại tài sản đã chiếm đoạt cho chủ sở hữu hoặc người quản lý hợp pháp, phải sửa chữa hoặc bồi thường thiệt hại vật chất đã được xác định do hành vi phạm tội gây ra.\r\n2. Trong trường hợp phạm tội gây thiệt hại về tinh thần, Tòa án buộc người phạm tội phải bồi thường về vật chất, công khai xin lỗi người bị hại.', 'law_48', '2024-05-02 11:54:15', '2024-05-02 11:54:15'),
(49, 'Điều 49. Bắt buộc chữa bệnh\r\n1. Đối với người thực hiện hành vi nguy hiểm cho xã hội trong khi mắc bệnh quy định tại Điều 21 của Bộ luật này, Viện kiểm sát hoặc Tòa án căn cứ vào kết luận giám định pháp y, giám định pháp y tâm thần có thể quyết định đưa họ vào một cơ sở điều trị chuyên khoa để bắt buộc chữa bệnh.\r\n2. Đối với người phạm tội trong khi có năng lực trách nhiệm hình sự nhưng trước khi bị kết án đã mắc bệnh tới mức mất khả năng nhận thức hoặc khả năng điều khiển hành vi của mình, thì căn cứ vào kết luận giám định pháp y, giám định pháp y tâm thần, Tòa án có thể quyết định đưa họ vào một cơ sở điều trị chuyên khoa để bắt buộc chữa bệnh. Sau khi khỏi bệnh, người đó có thể phải chịu trách nhiệm hình sự.\r\n3. Đối với người đang chấp hành hình phạt tù mà bị bệnh tới mức mất khả năng nhận thức hoặc khả năng điều khiển hành vi của mình, thì căn cứ vào kết luận giám định pháp y, giám định pháp y tâm thần, Tòa án có thể quyết định đưa họ vào một cơ sở điều trị chuyên khoa để bắt buộc chữa bệnh. Sau khi khỏi bệnh, nếu không có lý do khác để miễn chấp hành hình phạt, thì người đó phải tiếp tục chấp hành hình phạt.\r\nThời gian bắt buộc chữa bệnh được trừ vào thời hạn chấp hành hình phạt tù.', 'law_49', '2024-05-02 11:55:11', '2024-05-02 11:55:11'),
(50, 'Điều 50. Căn cứ quyết định hình phạt\r\n1. Khi quyết định hình phạt, Tòa án căn cứ vào quy định của Bộ luật này, cân nhắc tính chất và mức độ nguy hiểm cho xã hội của hành vi phạm tội, nhân thân người phạm tội, các tình tiết giảm nhẹ và tăng nặng trách nhiệm hình sự.\r\n2. Khi quyết định áp dụng hình phạt tiền, ngoài căn cứ quy định tại khoản 1 Điều này, Tòa án căn cứ vào tình hình tài sản, khả năng thi hành của người phạm tội.', 'law_50', '2024-05-02 11:55:11', '2024-05-02 11:55:11'),
(51, 'Điều 51. Các tình tiết giảm nhẹ trách nhiệm hình sự\r\n1. Các tình tiết sau đây là tình tiết giảm nhẹ trách nhiệm hình sự:\r\na) Người phạm tội đã ngăn chặn hoặc làm giảm bớt tác hại của tội phạm;\r\nb) Người phạm tội tự nguyện sửa chữa, bồi thường thiệt hại hoặc khắc phục hậu quả;\r\nc) Phạm tội trong trường hợp vượt quá giới hạn phòng vệ chính đáng;\r\nd) Phạm tội trong trường hợp vượt quá yêu cầu của tình thế cấp thiết;\r\nđ) Phạm tội trong trường hợp vượt quá mức cần thiết khi bắt giữ người phạm tội;\r\ne) Phạm tội trong trường hợp bị kích động về tinh thần do hành vi trái pháp luật của nạn nhân gây ra;\r\ng) Phạm tội vì hoàn cảnh đặc biệt khó khăn mà không phải do mình tự gây ra;\r\nh) Phạm tội nhưng chưa gây thiệt hại hoặc gây thiệt hại không lớn;\r\ni) Phạm tội lần đầu và thuộc trường hợp ít nghiêm trọng;\r\nk) Phạm tội vì bị người khác đe doạ hoặc cưỡng bức;\r\nl) Phạm tội trong trường hợp bị hạn chế khả năng nhận thức mà không phải do lỗi của mình gây ra;\r\nm) Phạm tội do lạc hậu;\r\nn) Người phạm tội là phụ nữ có thai;\r\no) Người phạm tội là người đủ 70 tuổi trở lên;\r\np) Người phạm tội là người khuyết tật nặng hoặc khuyết tật đặc biệt nặng;\r\nq) Người phạm tội là người có bệnh bị hạn chế khả năng nhận thức hoặc khả năng điều khiển hành vi của mình;\r\nr) Người phạm tội tự thú;\r\ns) Người phạm tội thành khẩn khai báo, ăn năn hối cải;\r\nt) Người phạm tội tích cực hợp tác với cơ quan có trách nhiệm trong việc phát hiện tội phạm hoặc trong quá trình giải quyết vụ án;\r\nu) Người phạm tội đã lập công chuộc tội;\r\nv) Người phạm tội là người có thành tích xuất sắc trong sản xuất, chiến đấu, học tập hoặc công tác;\r\nx) Người phạm tội là người có công với cách mạng hoặc là cha, mẹ, vợ, chồng, con của liệt sĩ.\r\n2. Khi quyết định hình phạt, Tòa án có thể coi đầu thú hoặc tình tiết khác là tình tiết giảm nhẹ, nhưng phải ghi rõ lý do giảm nhẹ trong bản án.\r\n3. Các tình tiết giảm nhẹ đã được Bộ luật này quy định là dấu hiệu định tội hoặc định khung thì không được coi là tình tiết giảm nhẹ trong khi quyết định hình phạt.', 'law_51', '2024-05-02 23:45:37', '2024-05-02 23:57:37'),
(52, 'Điều 52. Các tình tiết tăng nặng trách nhiệm hình sự\r\n1. Chỉ các tình tiết sau đây mới là tình tiết tăng nặng trách nhiệm hình sự:\r\na) Phạm tội có tổ chức;\r\nb) Phạm tội có tính chất chuyên nghiệp;\r\nc) Lợi dụng chức vụ, quyền hạn để phạm tội;\r\nd) Phạm tội có tính chất côn đồ;\r\nđ) Phạm tội vì động cơ đê hèn;\r\ne) Cố tình thực hiện tội phạm đến cùng;\r\ng) Phạm tội 02 lần trở lên;\r\nh) Tái phạm hoặc tái phạm nguy hiểm;\r\ni) Phạm tội đối với người dưới 16 tuổi, phụ nữ có thai, người đủ 70 tuổi trở lên;\r\nk) Phạm tội đối với người ở trong tình trạng không thể tự vệ được, người khuyết tật nặng hoặc khuyết tật đặc biệt nặng, người bị hạn chế khả năng nhận thức hoặc người lệ thuộc mình về mặt vật chất, tinh thần, công tác hoặc các mặt khác;\r\nl) Lợi dụng hoàn cảnh chiến tranh, tình trạng khẩn cấp, thiên tai, dịch bệnh hoặc những khó khăn đặc biệt khác của xã hội để phạm tội;\r\nm) Dùng thủ đoạn tinh vi, xảo quyệt, tàn ác để phạm tội;\r\nn) Dùng thủ đoạn, phương tiện có khả năng gây nguy hại cho nhiều người để phạm tội;\r\no) Xúi giục người dưới 18 tuổi phạm tội;\r\np) Có hành động xảo quyệt hoặc hung hãn nhằm trốn tránh hoặc che giấu tội phạm.\r\n2. Các tình tiết đã được Bộ luật này quy định là dấu hiệu định tội hoặc định khung hình phạt thì không được coi là tình tiết tăng nặng.', 'law_52', '2024-05-02 23:45:37', '2024-05-02 23:57:42'),
(53, 'Điều 53. Tái phạm, tái phạm nguy hiểm\r\n1. Tái phạm là trường hợp đã bị kết án, chưa được xóa án tích mà lại thực hiện hành vi phạm tội do cố ý hoặc thực hiện hành vi phạm tội về tội phạm rất nghiêm trọng, tội phạm đặc biệt nghiêm trọng do vô ý.\r\n2. Những trường hợp sau đây được coi là tái phạm nguy hiểm:\r\na) Đã bị kết án về tội phạm rất nghiêm trọng, tội phạm đặc biệt nghiêm trọng do cố ý, chưa được xóa án tích mà lại thực hiện hành vi phạm tội về tội phạm rất nghiêm trọng, tội phạm đặc biệt nghiêm trọng do cố ý;\r\nb) Đã tái phạm, chưa được xóa án tích mà lại thực hiện hành vi phạm tội do cố ý.', 'law_53', '2024-05-02 23:45:37', '2024-05-02 23:57:52'),
(54, 'Điều 54. Quyết định hình phạt dưới mức thấp nhất của khung hình phạt được áp dụng\r\n1. Tòa án có thể quyết định một hình phạt dưới mức thấp nhất của khung hình phạt được áp dụng nhưng phải trong khung hình phạt liền kề nhẹ hơn của điều luật khi người phạm tội có ít nhất hai tình tiết giảm nhẹ quy định tại khoản 1 Điều 51 của Bộ luật này.\r\n2. Tòa án có thể quyết định một hình phạt dưới mức thấp nhất của khung hình phạt được áp dụng nhưng không bắt buộc phải trong khung hình phạt liền kề nhẹ hơn của điều luật đối với người phạm tội lần đầu là người giúp sức trong vụ án đồng phạm nhưng có vai trò không đáng kể.\r\n3. Trong trường hợp có đủ các điều kiện quy định tại khoản 1 hoặc khoản 2 Điều này nhưng điều luật chỉ có một khung hình phạt hoặc khung hình phạt đó là khung hình phạt nhẹ nhất, thì Tòa án có thể quyết định hình phạt dưới mức thấp nhất của khung hình phạt hoặc chuyển sang một hình phạt khác thuộc loại nhẹ hơn. Lý do của việc giảm nhẹ phải được ghi rõ trong bản án.', 'law_54', '2024-05-02 23:45:37', '2024-05-02 23:57:57'),
(55, 'Điều 55. Quyết định hình phạt trong trường hợp phạm nhiều tội\r\nKhi xét xử cùng 01 lần một người phạm nhiều tội, Tòa án quyết định hình phạt đối với từng tội và tổng hợp hình phạt theo quy định sau đây:\r\n1. Đối với hình phạt chính:\r\na) Nếu các hình phạt đã tuyên cùng là cải tạo không giam giữ hoặc cùng là tù có thời hạn, thì các hình phạt đó được cộng lại thành hình phạt chung; hình phạt chung không được vượt quá 03 năm đối với hình phạt cải tạo không giam giữ, 30 năm đối với hình phạt tù có thời hạn;\r\nb) Nếu các hình phạt đã tuyên là cải tạo không giam giữ, tù có thời hạn, thì hình phạt cải tạo không giam giữ được chuyển đổi thành hình phạt tù theo tỷ lệ cứ 03 ngày cải tạo không giam giữ được chuyển đổi thành 01 ngày tù để tổng hợp thành hình phạt chung theo quy định tại điểm a khoản 1 Điều này;\r\nc) Nếu hình phạt nặng nhất trong số các hình phạt đã tuyên là tù chung thân thì hình phạt chung là tù chung thân;\r\nd) Nếu hình phạt nặng nhất trong số các hình phạt đã tuyên là tử hình thì hình phạt chung là tử hình;\r\nđ) Phạt tiền không tổng hợp với các loại hình phạt khác; các khoản tiền phạt được cộng lại thành hình phạt chung;\r\ne) Trục xuất không tổng hợp với các loại hình phạt khác;\r\n2. Đối với hình phạt bổ sung:\r\na) Nếu các hình phạt đã tuyên là cùng loại thì hình phạt chung được quyết định trong giới hạn do Bộ luật này quy định đối với loại hình phạt đó; riêng đối với hình phạt tiền thì các khoản tiền phạt được cộng lại thành hình phạt chung;\r\nb) Nếu các hình phạt đã tuyên là khác loại thì người bị kết án phải chấp hành tất cả các hình phạt đã tuyên.', 'law_55', '2024-05-02 23:45:37', '2024-05-02 23:58:24'),
(56, 'Điều 56. Tổng hợp hình phạt của nhiều bản án\r\n1. Trong trường hợp một người đang phải chấp hành một bản án mà lại bị xét xử về tội đã phạm trước khi có bản án này, thì Tòa án quyết định hình phạt đối với tội đang bị xét xử, sau đó quyết định hình phạt chung theo quy định tại Điều 55 của Bộ luật này.\r\nThời gian đã chấp hành hình phạt của bản án trước được trừ vào thời hạn chấp hành hình phạt chung.\r\n2. Khi xét xử một người đang phải chấp hành một bản án mà lại thực hiện hành vi phạm tội mới, Tòa án quyết định hình phạt đối với tội mới, sau đó tổng hợp với phần hình phạt chưa chấp hành của bản án trước rồi quyết định hình phạt chung theo quy định tại Điều 55 của Bộ luật này.\r\n3. Trong trường hợp một người phải chấp hành nhiều bản án đã có hiệu lực pháp luật mà các hình phạt của các bản án chưa được tổng hợp, thì Chánh án Tòa án có thẩm quyền ra quyết định tổng hợp hình phạt của các bản án theo quy định tại khoản 1 và khoản 2 Điều này.', 'law_56', '2024-05-02 23:45:37', '2024-05-02 23:58:52'),
(57, 'Điều 57. Quyết định hình phạt trong trường hợp chuẩn bị phạm tội, phạm tội chưa đạt\r\n1. Đối với hành vi chuẩn bị phạm tội và hành vi phạm tội chưa đạt, hình phạt được quyết định theo các điều của Bộ luật này về các tội phạm tương ứng tùy theo tính chất, mức độ nguy hiểm cho xã hội của hành vi, mức độ thực hiện ý định phạm tội và những tình tiết khác khiến cho tội phạm không thực hiện được đến cùng.\r\n2. Đối với trường hợp chuẩn bị phạm tội, hình phạt được quyết định trong phạm vi khung hình phạt được quy định trong các điều luật cụ thể.\r\n3. Đối với trường hợp phạm tội chưa đạt, nếu điều luật được áp dụng có quy định hình phạt cao nhất là tù chung thân hoặc tử hình thì áp dụng hình phạt tù không quá 20 năm; nếu là tù có thời hạn thì mức hình phạt không quá ba phần tư mức phạt tù mà điều luật quy định.', 'law_57', '2024-05-02 23:45:37', '2024-05-02 23:58:57'),
(58, 'Điều 58. Quyết định hình phạt trong trường hợp đồng phạm\r\nKhi quyết định hình phạt đối với những người đồng phạm, Tòa án phải xét đến tính chất của đồng phạm, tính chất và mức độ tham gia phạm tội của từng người đồng phạm.\r\nCác tình tiết giảm nhẹ, tăng nặng hoặc loại trừ trách nhiệm hình sự thuộc người đồng phạm nào, thì chỉ áp dụng đối với người đó.', 'law_58', '2024-05-02 23:45:37', '2024-05-02 23:59:01'),
(59, 'Điều 59. Miễn hình phạt\r\nNgười phạm tội có thể được miễn hình phạt nếu thuộc trường hợp quy định tại khoản 1 và khoản 2 Điều 54 của Bộ luật này mà đáng được khoan hồng đặc biệt nhưng chưa đến mức được miễn trách nhiệm hình sự.', 'law_59', '2024-05-02 23:45:37', '2024-05-02 23:59:05'),
(60, 'Điều 60. Thời hiệu thi hành bản án\r\n1. Thời hiệu thi hành bản án hình sự là thời hạn do Bộ luật này quy định mà khi hết thời hạn đó người bị kết án, pháp nhân thương mại bị kết án không phải chấp hành bản án đã tuyên.\r\n2. Thời hiệu thi hành bản án hình sự đối với người bị kết án được quy định như sau:\r\na) 05 năm đối với các trường hợp xử phạt tiền, cải tạo không giam giữ hoặc xử phạt tù từ 03 năm trở xuống;\r\nb) 10 năm đối với các trường hợp xử phạt tù từ trên 03 năm đến 15 năm;\r\nc) 15 năm đối với các trường hợp xử phạt tù từ trên 15 năm đến 30 năm;\r\nd) 20 năm đối với các trường hợp xử phạt tù chung thân hoặc tử hình.\r\n3. Thời hiệu thi hành bản án hình sự đối với pháp nhân thương mại là 05 năm.\r\n4. Thời hiệu thi hành bản án hình sự được tính từ ngày bản án có hiệu lực pháp luật. Nếu trong thời hạn quy định tại khoản 2 và khoản 3 Điều này, người bị kết án, pháp nhân thương mại bị kết án lại thực hiện hành vi phạm tội mới, thì thời hiệu tính lại kể từ ngày thực hiện hành vi phạm tội mới.\r\n5. Trong thời hạn quy định tại khoản 2 Điều này, người bị kết án cố tình trốn tránh và đã có quyết định truy nã, thì thời hiệu tính lại kể từ ngày người đó ra trình diện hoặc bị bắt giữ.', 'law_60', '2024-05-02 23:45:37', '2024-05-02 23:59:13'),
(61, 'Điều 61. Không áp dụng thời hiệu thi hành bản án\r\nKhông áp dụng thời hiệu thi hành bản án đối với các tội quy định tại Chương XIII, Chương XXVI, khoản 3 và khoản 4 Điều 353, khoản 3 và khoản 4 Điều 354 của Bộ luật này.', 'law_61', '2024-05-02 23:45:37', '2024-05-02 23:59:19');
INSERT INTO `tbl_chatbot_responses` (`chatbot_responses_id`, `chatbot_responses`, `intent_group_name`, `created_datetime`, `updated_datetime`) VALUES
(62, 'Điều 62. Miễn chấp hành hình phạt\r\n1. Người bị kết án được miễn chấp hành hình phạt khi được đặc xá hoặc đại xá.\r\n2. Người bị kết án cải tạo không giam giữ hoặc tù có thời hạn đến 03 năm chưa chấp hành hình phạt thì theo đề nghị của Viện trưởng Viện kiểm sát, Tòa án có thể quyết định miễn chấp hành hình phạt, nếu thuộc một trong các trường hợp sau đây:\r\na) Sau khi bị kết án đã lập công;\r\nb) Mắc bệnh hiểm nghèo;\r\nc) Chấp hành tốt pháp luật, có hoàn cảnh gia đình đặc biệt khó khăn và xét thấy người đó không còn nguy hiểm cho xã hội nữa.\r\n3. Người bị kết án phạt tù có thời hạn trên 03 năm, chưa chấp hành hình phạt nếu đã lập công lớn hoặc mắc bệnh hiểm nghèo và người đó không còn nguy hiểm cho xã hội nữa, thì theo đề nghị của Viện trưởng Viện kiểm sát, Tòa án có thể quyết định miễn chấp hành toàn bộ hình phạt.\r\n4. Người bị kết án phạt tù đến 03 năm, đã được tạm đình chỉ chấp hành hình phạt, nếu trong thời gian được tạm đình chỉ mà đã lập công hoặc chấp hành tốt pháp luật, hoàn cảnh gia đình đặc biệt khó khăn và xét thấy người đó không còn nguy hiểm cho xã hội nữa, thì theo đề nghị của Viện trưởng Viện kiểm sát, Tòa án có thể quyết định miễn chấp hành phần hình phạt còn lại.\r\n5. Người bị kết án phạt tiền đã tích cực chấp hành được một phần hình phạt nhưng bị lâm vào hoàn cảnh kinh tế đặc biệt khó khăn kéo dài do thiên tai, hoả hoạn, tai nạn hoặc ốm đau gây ra mà không thể tiếp tục chấp hành được phần hình phạt còn lại hoặc lập công lớn, thì theo đề nghị của Viện trưởng Viện kiểm sát, Tòa án có thể quyết đinh miễn chấp hành phần tiền phạt còn lại.\r\n6. Người bị phạt cấm cư trú hoặc quản chế, nếu đã chấp hành được một phần hai thời hạn hình phạt và cải tạo tốt, thì theo đề nghị của cơ quan thi hành án hình sự cấp huyện nơi người đó chấp hành hình phạt, Tòa án có thể quyết định miễn chấp hành phần hình phạt còn lại.\r\n7. Người được miễn chấp hành hình phạt theo quy định tại Điều này vẫn phải thực hiện đầy đủ các nghĩa vụ dân sự do Tòa án tuyên trong bản án.', 'law_62', '2024-05-02 23:45:37', '2024-05-02 23:59:24'),
(63, 'Điều 63. Giảm mức hình phạt đã tuyên\r\n1. Người bị kết án cải tạo không giam giữ, phạt tù có thời hạn hoặc phạt tù chung thân, nếu đã chấp hành hình phạt được một thời gian nhất định, có nhiều tiến bộ và đã bồi thường được một phần nghĩa vụ dân sự, thì theo đề nghị của cơ quan thi hành án hình sự có thẩm quyền, Tòa án có thể quyết định giảm thời hạn chấp hành hình phạt.\r\nThời gian đã chấp hành hình phạt để được xét giảm lần đầu là một phần ba thời hạn đối với hình phạt cải tạo không giam giữ, hình phạt tù có thời hạn, 12 năm đối với tù chung thân.\r\n2. Một người có thể được giảm nhiều lần, nhưng phải bảo đảm chấp hành được một phần hai mức hình phạt đã tuyên.\r\nNgười bị kết án tù chung thân, lần đầu được giảm xuống 30 năm tù và dù được giảm nhiều lần cũng phải bảo đảm thời hạn thực tế chấp hành hình phạt là 20 năm.\r\n3. Trường hợp người bị kết án về nhiều tội trong đó có tội bị kết án phạt tù chung thân thì Tòa án chỉ xét giảm lần đầu xuống 30 năm tù sau khi đã chấp hành được 15 năm tù và dù được giảm nhiều lần nhưng vẫn phải bảo đảm thời gian thực tế chấp hành là 25 năm.\r\n4. Đối với người đã được giảm một phần hình phạt mà lại thực hiện hành vi phạm tội mới ít nghiêm trọng do cố ý, thì Tòa án chỉ xét giảm lần đầu sau khi người đó đã chấp hành được một phần hai mức hình phạt chung.\r\n5. Đối với người đã được giảm một phần hình phạt mà lại thực hiện hành vi phạm tội mới nghiêm trọng, rất nghiêm trọng hoặc đặc biệt nghiêm trọng, thì Tòa án chỉ xét giảm lần đầu sau khi người đó đã chấp hành được hai phần ba mức hình phạt chung hoặc trường hợp hình phạt chung là tù chung thân thì việc xét giảm án thực hiện theo quy định tại khoản 3 Điều này.\r\n6. Đối với người bị kết án tử hình được ân giảm hoặc người bị kết án tử hình thuộc trường hợp quy định tại điểm b hoặc điểm c khoản 3 Điều 40 của Bộ luật này thì thời gian ðã chấp hành hình phạt để được xét giảm lần đầu là 25 năm và dù được giảm nhiều lần nhưng vẫn phải bảo đảm thời hạn thực tế chấp hành hình phạt là 30 năm.', 'law_63', '2024-05-02 23:45:37', '2024-05-02 23:59:28'),
(64, 'Điều 64. Giảm thời hạn chấp hành hình phạt trong trường hợp đặc biệt\r\nNgười bị kết án có lý do đáng được khoan hồng thêm như đã lập công, đã quá già yếu hoặc mắc bệnh hiểm nghèo, thì Tòa án có thể xét giảm vào thời gian sớm hơn hoặc với mức cao hơn so với thời gian và mức quy định tại Điều 63 của Bộ luật này.', 'law_64', '2024-05-02 23:45:37', '2024-05-02 23:59:34'),
(65, 'Điều 65. Án treo\r\n1. Khi xử phạt tù không quá 03 năm, căn cứ vào nhân thân của người phạm tội và các tình tiết giảm nhẹ, nếu xét thấy không cần phải bắt chấp hành hình phạt tù, thì Tòa án cho hưởng án treo và ấn định thời gian thử thách từ 01 năm đến 05 năm và thực hiện các nghĩa vụ trong thời gian thử thách theo quy định của Luật thi hành án hình sự.\r\n2. Trong thời gian thử thách, Tòa án giao người được hưởng án treo cho cơ quan, tổ chức nơi người đó làm việc hoặc chính quyền địa phương nơi người đó cư trú để giám sát, giáo dục. Gia đình người bị kết án có trách nhiệm phối hợp với cơ quan, tổ chức, chính quyền địa phương trong việc giám sát, giáo dục người đó.\r\n3. Tòa án có thể quyết định áp dụng đối với người được hưởng án treo hình phạt bổ sung nếu trong điều luật áp dụng có quy định hình phạt này.\r\n4. Người được hưởng án treo đã chấp hành được một phần hai thời gian thử thách và có nhiều tiến bộ thì theo đề nghị của cơ quan, tổ chức có trách nhiệm giám sát, giáo dục, Tòa án có thể quyết định rút ngắn thời gian thử thách.\r\n5. Trong thời gian thử thách, nếu người được hưởng án treo cố ý vi phạm nghĩa vụ theo quy định của Luật thi hành án hình sự 02 lần trở lên, thì Tòa án có thể quyết định buộc người đó phải chấp hành hình phạt tù của bản án đã cho hưởng án treo. Trường hợp thực hiện hành vi phạm tội mới thì Tòa án buộc người đó phải chấp hành hình phạt của bản án trước và tổng hợp với hình phạt của bản án mới theo quy định tại Điều 56 của Bộ luật này.', 'law_65', '2024-05-02 23:45:37', '2024-05-02 23:59:38'),
(66, 'Điều 66. Tha tù trước thời hạn có điều kiện\r\n1. Người đang chấp hành án phạt tù về tội phạm nghiêm trọng, tội phạm rất nghiêm trọng hoặc tội phạm đặc biệt nghiêm trọng mà đã được giảm thời hạn chấp hành án phạt tù hoặc người đang chấp hành án phạt tù về tội phạm ít nghiêm trọng có thể được tha tù trước thời hạn khi có đủ các điều kiện sau đây:\r\na) Phạm tội lần đầu;\r\nb) Có nhiều tiến bộ, có ý thức cải tạo tốt;\r\nc) Có nơi cư trú rõ ràng;\r\nd) Đã chấp hành xong hình phạt bổ sung là hình phạt tiền, nghĩa vụ bồi thường thiệt hại và án phí;\r\nđ) Đã chấp hành được ít nhất là một phần hai mức phạt tù có thời hạn hoặc ít nhất là 15 năm đối với trường hợp bị phạt tù chung thân nhưng đã được giảm xuống tù có thời hạn.\r\nTrường hợp người phạm tội là người có công với cách mạng, thân nhân của người có công với cách mạng, người đủ 70 tuổi trở lên, người khuyết tật nặng hoặc khuyết tật đặc biệt nặng, phụ nữ đang nuôi con dưới 36 tháng tuổi thì phải chấp hành được ít nhất là một phần ba mức phạt tù có thời hạn hoặc ít nhất là 12 năm đối với trường hợp bị phạt tù chung thân nhưng đã được giảm xuống tù có thời hạn;\r\ne) Không thuộc một trong các trường hợp phạm tội quy định tại khoản 2 Điều này.\r\n2. Không áp dụng quy định của Điều này đối với người bị kết án thuộc một trong các trường hợp sau đây:\r\na) Người bị kết án về một trong các tội quy định tại Chương XIII, Chương XXVI, Điều 299 của Bộ luật này; người bị kết án 10 năm tù trở lên về một trong các tội quy định tại Chương XIV của Bộ luật này do cố ý hoặc người bị kết án 07 năm tù trở lên đối với một trong các tội quy định tại các điều 168, 169, 248, 251 và 252 của Bộ luật này;\r\nb) Người bị kết án tử hình được ân giảm hoặc thuộc trường hợp quy định tại khoản 3 Điều 40 của Bộ luật này.\r\n3. Theo đề nghị của cơ quan thi hành án hình sự có thẩm quyền, Tòa án quyết định tha tù trước thời hạn có điều kiện đối với người bị kết án. Người được tha tù trước thời hạn có điều kiện phải thực hiện các nghĩa vụ trong thời gian thử thách. Thời gian thử thách bằng thời gian còn lại của hình phạt tù.\r\n4. Người được tha tù trước thời hạn có điều kiện cố ý vi phạm nghĩa vụ 02 lần trở lên hoặc bị xử phạt vi phạm hành chính 02 lần trở lên trong thời gian thử thách, thì Tòa án có thể hủy bỏ quyết định tha tù trước thời hạn có điều kiện đối với người đó và buộc họ phải chấp hành phần hình phạt tù còn lại chưa chấp hành.\r\nNếu người đó thực hiện hành vi phạm tội mới trong thời gian thử thách thì Tòa án buộc người đó chấp hành hình phạt của bản án mới và tổng hợp với phần hình phạt tù chưa chấp hành của bản án trước theo quy định tại Điều 56 của Bộ luật này.\r\n5. Người được tha tù trước thời hạn có điều kiện đã chấp hành được ít nhất là một phần hai thời gian thử thách và có nhiều tiến bộ thì theo đề nghị của cơ quan thi hành án hình sự có thẩm quyền, Tòa án có thể quyết định rút ngắn thời gian thử thách.', 'law_66', '2024-05-02 23:45:37', '2024-05-02 23:59:41'),
(67, 'Điều 67. Hoãn chấp hành hình phạt tù\r\n1. Người bị xử phạt tù có thể được hoãn chấp hành hình phạt trong các trường hợp sau đây:\r\na) Bị bệnh nặng thì được hoãn cho đến khi sức khỏe được hồi phục;\r\nb) Phụ nữ có thai hoặc đang nuôi con dưới 36 tháng tuổi, thì được hoãn cho đến khi con đủ 36 tháng tuổi;\r\nc) Là người lao động duy nhất trong gia đình, nếu phải chấp hành hình phạt tù thì gia đình sẽ gặp khó khăn đặc biệt, được hoãn đến 01 năm, trừ trường hợp người đó bị kết án về các tội xâm phạm an ninh quốc gia hoặc các tội khác là tội phạm rất nghiêm trọng, tội phạm đặc biệt nghiêm trọng;\r\nd) Bị kết án về tội phạm ít nghiêm trọng, do nhu cầu công vụ, thì được hoãn đến 01 năm.\r\n2. Trong thời gian được hoãn chấp hành hình phạt tù, nếu người được hoãn chấp hành hình phạt lại thực hiện hành vi phạm tội mới, thì Tòa án buộc người đó phải chấp hành hình phạt trước và tổng hợp với hình phạt của bản án mới theo quy định tại Điều 56 của Bộ luật này.', 'law_67', '2024-05-02 23:45:37', '2024-05-02 23:59:45'),
(68, 'Điều 68. Tạm đình chỉ chấp hành hình phạt tù\r\n1. Người đang chấp hành hình phạt tù mà thuộc một trong các trường hợp quy định tại khoản 1 Điều 67 của Bộ luật này, thì có thể được tạm đình chỉ chấp hành hình phạt tù.\r\n2. Thời gian tạm đình chỉ không được tính vào thời gian chấp hành hình phạt tù.', 'law_68', '2024-05-02 23:45:37', '2024-05-02 23:59:49'),
(69, 'Điều 69. Xóa án tích\r\n1. Người bị kết án được xóa án tích theo quy định tại các điều từ Điều 70 đến Điều 73 của Bộ luật này.\r\nNgười được xóa án tích coi như chưa bị kết án.\r\n2. Người bị kết án do lỗi vô ý về tội phạm ít nghiêm trọng, tội phạm nghiêm trọng và người được miễn hình phạt không bị coi là có án tích.', 'law_69', '2024-05-02 23:45:37', '2024-05-02 23:59:52'),
(70, 'Điều 70. Đương nhiên được xóa án tích\r\n1. Đương nhiên được xóa án tích được áp dụng đối với người bị kết án không phải về các tội quy định tại Chương XIII và Chương XXVI của Bộ luật này khi họ đã chấp hành xong hình phạt chính, thời gian thử thách án treo hoặc hết thời hiệu thi hành bản án và đáp ứng các điều kiện quy định tại khoản 2 và khoản 3 Điều này.\r\n2. Người bị kết án đương nhiên được xóa án tích, nếu từ khi chấp hành xong hình phạt chính hoặc hết thời gian thử thách án treo, người đó đã chấp hành xong hình phạt bổ sung, các quyết định khác của bản án và không thực hiện hành vi phạm tội mới trong thời hạn sau đây:\r\na) 01 năm trong trường hợp bị phạt cảnh cáo, phạt tiền, cải tạo không giam giữ, phạt tù nhưng được hưởng án treo;\r\nb) 02 năm trong trong trường hợp bị phạt tù đến 05 năm;\r\nc) 03 năm trong trường hợp bị phạt tù từ trên 05 năm đến 15 năm;\r\nd) 05 năm trong trường hợp bị phạt tù từ trên 15 năm, tù chung thân hoặc tử hình nhưng đã được giảm án.\r\nTrường hợp người bị kết án đang chấp hành hình phạt bổ sung là quản chế, cấm cư trú, cấm đảm nhiệm chức vụ, cấm hành nghề hoặc làm công việc nhất định, tước một số quyền công dân mà thời hạn phải chấp hành dài hơn thời hạn quy định tại các điểm a, b và c khoản này thì thời hạn đương nhiên được xóa án tích sẽ hết vào thời điểm người đó chấp hành xong hình phạt bổ sung.\r\n3. Người bị kết án đương nhiên được xóa án tích, nếu từ khi hết thời hiệu thi hành bản án, người đó không thực hiện hành vi phạm tội mới trong thời hạn quy định tại khoản 2 Điều này.\r\n4. Cơ quan quản lý cơ sở dữ liệu lý lịch tư pháp có trách nhiệm cập nhật thông tin về tình hình án tích của người bị kết án và khi có yêu cầu thì cấp phiếu lý lịch tư pháp xác nhận không có án tích, nếu có đủ điều kiện quy định tại khoản 2 hoặc khoản 3 Điều này.', 'law_70', '2024-05-02 23:45:37', '2024-05-02 23:59:56'),
(71, 'Điều 71. Xóa án tích theo quyết định của Tòa án\r\n1. Xóa án tích theo quyết định của Tòa án được áp dụng đối với người bị kết án về một trong các tội quy định tại Chương XIII và Chương XXVI của Bộ luật này. Tòa án quyết định việc xóa án tích đối với người bị kết án căn cứ vào tính chất của tội phạm đã thực hiện, thái độ chấp hành pháp luật, thái độ lao động của người bị kết án và các điều kiện quy định tại khoản 2 Điều này.\r\n2. Người bị kết án được Tòa án quyết định việc xóa án tích, nếu từ khi chấp hành xong hình phạt chính hoặc hết thời gian thử thách án treo, người đó đã chấp hành xong hình phạt bổ sung, các quyết định khác của bản án và không thực hiện hành vi phạm tội mới trong thời hạn sau đây:\r\na) 01 năm trong trường hợp bị phạt cảnh cáo, phạt cải tạo không giam giữ, phạt tù nhưng được hưởng án treo;\r\nb) 03 năm trong trường hợp bị phạt tù đến 05 năm;\r\nc) 05 năm trong trường hợp bị phạt tù từ trên 05 năm đến 15 năm;\r\nd) 07 năm trong trường hợp bị phạt tù trên 15 năm, tù chung thân hoặc tử hình nhưng đã được giảm án.\r\nTrường hợp người bị kết án đang chấp hành hình phạt bổ sung là quản chế, cấm cư trú, tước một số quyền công dân mà thời hạn phải chấp hành dài hơn thời hạn quy định tại điểm a, điểm b khoản này thì Tòa án quyết định việc xóa án tích từ khi người đó chấp hành xong hình phạt bổ sung.\r\n3. Người bị Tòa án bác đơn xin xóa án tích lần đầu, thì sau 01 năm kể từ ngày bị Tòa án bác đơn mới được xin xóa án tích; nếu bị bác đơn lần thứ hai trở đi, thì sau 02 năm kể từ ngày bị Tòa án bác đơn mới được xin xóa án tích.', 'law_71', '2024-05-02 23:45:37', '2024-05-03 00:00:00'),
(72, 'Điều 72. Xóa án tích trong trường hợp đặc biệt\r\nTrong trường hợp người bị kết án có những biểu hiện tiến bộ rõ rệt và đã lập công, được cơ quan, tổ chức nơi người đó công tác hoặc chính quyền địa phương nơi người đó cư trú đề nghị, thì Tòa án quyết định việc xóa án tích nếu người đó đã bảo đảm được ít nhất một phần ba thời hạn quy định tại khoản 2 Điều 70 và khoản 2 Điều 71 của Bộ luật này.', 'law_72', '2024-05-02 23:45:37', '2024-05-03 00:00:03'),
(73, 'Điều 73. Cách tính thời hạn để xóa án tích\r\n1. Thời hạn để xóa án tích quy định tại Điều 70 và Điều 71 của Bộ luật này căn cứ vào hình phạt chính đã tuyên.\r\n2. Người bị kết án chưa được xóa án tích mà thực hiện hành vi phạm tội mới và bị Tòa án kết án bằng bản án có hiệu lực pháp luật thì thời hạn để xóa án tích cũ được tính lại kể từ ngày chấp hành xong hình phạt chính hoặc thời gian thử thách án treo của bản án mới hoặc từ ngày bản án mới hết thời hiệu thi hành.\r\n3. Người bị kết án trong trường hợp phạm nhiều tội mà có tội thuộc trường hợp đương nhiên được xóa án tích, có tội thuộc trường hợp xóa án tích theo quyết định của Tòa án thì căn cứ vào thời hạn quy định tại Điều 71 của Bộ luật này Tòa án quyết định việc xóa án tích đối với người đó.\r\n4. Người được miễn chấp hành phần hình phạt còn lại cũng được coi như đã chấp hành xong hình phạt.', 'law_73', '2024-05-02 23:45:37', '2024-05-03 00:00:06'),
(74, 'Điều 74. Áp dụng quy định của Bộ luật hình sự đối với pháp nhân thương mại phạm tội\r\nPháp nhân thương mại phạm tội phải chịu trách nhiệm hình sự theo những quy định của Chương này; theo quy định khác của Phần thứ nhất của Bộ luật này không trái với quy định của Chương này.', 'law_74', '2024-05-02 23:45:37', '2024-05-03 00:00:10'),
(75, 'Điều 75. Điều kiện chịu trách nhiệm hình sự của pháp nhân thương mại\r\n1. Pháp nhân thương mại chỉ phải chịu trách nhiệm hình sự khi có đủ các điều kiện sau đây:\r\na) Hành vi phạm tội được thực hiện nhân danh pháp nhân thương mại;\r\nb) Hành vi phạm tội được thực hiện vì lợi ích của pháp nhân thương mại;\r\nc) Hành vi phạm tội được thực hiện có sự chỉ đạo, điều hành hoặc chấp thuận của pháp nhân thương mại;\r\nd) Chưa hết thời hiệu truy cứu trách nhiệm hình sự quy định tại khoản 2 và khoản 3 Điều 27 của Bộ luật này.\r\n2. Việc pháp nhân thương mại chịu trách nhiệm hình sự không loại trừ trách nhiệm hình sự của cá nhân.', 'law_75', '2024-05-02 23:45:37', '2024-05-03 00:00:15'),
(76, 'Điều 76. Phạm vi chịu trách nhiệm hình sự của pháp nhân thương mại\r\nPháp nhân thương mại phải chịu trách nhiệm hình sự về tội phạm quy định tại một trong các điều 188, 189, 190, 191, 192, 193, 194, 195, 196, 200, 203, 209, 210, 211, 213, 216, 217, 225, 226, 227, 232, 234, 235, 237, 238, 239, 242, 243, 244, 245, 246, 300 và 324 của Bộ luật này.\r\n', 'law_76', '2024-05-02 23:55:55', '2024-05-03 00:00:19'),
(77, 'Điều 77. Phạt tiền\r\n1. Phạt tiền được áp dụng là hình phạt chính hoặc hình phạt bổ sung đối với pháp nhân thương mại phạm tội.\r\n2. Mức tiền phạt được quyết định căn cứ vào tính chất, mức độ nguy hiểm của tội phạm và có xét đến tình hình tài chính của pháp nhân thương mại phạm tội, sự biến động của giá cả nhưng không được thấp hơn 50.000.000 đồng.\r\n', 'law_77', '2024-05-02 23:55:55', '2024-05-03 00:00:57'),
(78, 'Điều 78. Đình chỉ hoạt động có thời hạn\r\n1. Đình chỉ hoạt động có thời hạn là tạm dừng hoạt động của pháp nhân thương mại trong một hoặc một số lĩnh vực mà pháp nhân thương mại phạm tội gây thiệt hại đến tính mạng, sức khỏe con người, môi trường hoặc an ninh, trật tự, an toàn xã hội và hậu quả gây ra có khả năng khắc phục trên thực tế.\r\n2. Thời hạn đình chỉ hoạt động từ 06 tháng đến 03 năm.', 'law_78', '2024-05-02 23:55:55', '2024-05-03 00:01:41'),
(79, 'Điều 79. Đình chỉ hoạt động vĩnh viễn\r\n1. Đình chỉ hoạt động vĩnh viễn là chấm dứt hoạt động của pháp nhân thương mại trong một hoặc một số lĩnh vực mà pháp nhân thương mại phạm tội gây thiệt hại hoặc có khả năng thực tế gây thiệt hại đến tính mạng của nhiều người, gây sự cố môi trường hoặc gây ảnh hưởng xấu đến an ninh, trật tự, an toàn xã hội và không có khả năng khắc phục hậu quả gây ra.\r\n2. Pháp nhân thương mại được thành lập chỉ để thực hiện tội phạm thì bị đình chỉ vĩnh viễn toàn bộ hoạt động.', 'law_79', '2024-05-02 23:55:55', '2024-05-03 00:01:45'),
(80, 'Điều 80. Cấm kinh doanh, cấm hoạt động trong một số lĩnh vực nhất định\r\n1. Cấm kinh doanh, cấm hoạt động trong một số lĩnh vực nhất định được áp dụng khi xét thấy nếu để pháp nhân thương mại bị kết án tiếp tục kinh doanh hoặc hoạt động trong lĩnh vực đó, thì có thể gây nguy hại cho tính mạng, sức khỏe của con người hoặc cho xã hội.\r\n2. Tòa án quyết định lĩnh vực cụ thể bị cấm kinh doanh hoặc cấm hoạt động.\r\n3. Thời hạn cấm kinh doanh, cấm hoạt động trong một số lĩnh vực nhất định là từ 01 năm đến 03 năm, kể từ ngày bản án có hiệu lực pháp luật.', 'law_80', '2024-05-02 23:55:55', '2024-05-03 00:01:56'),
(81, 'Điều 81. Cấm huy động vốn\r\n1. Cấm huy động vốn được áp dụng khi xét thấy nếu để pháp nhân thương mại bị kết án huy động vốn thì có nguy cơ tiếp tục phạm tội.\r\n2. Các hình thức cấm huy động vốn bao gồm:\r\na) Cấm vay vốn ngân hàng, tổ chức tín dụng hoặc các quỹ đầu tư;\r\nb) Cấm phát hành, chào bán chứng khoán;\r\nc) Cấm huy động vốn khách hàng;\r\nd) Cấm liên doanh, liên kết trong và ngoài nước;\r\nđ) Cấm hình thành quỹ tín thác bất động sản.\r\n3. Tòa án quyết định áp dụng một hoặc một số hình thức cấm huy động vốn quy định tại khoản 2 Điều này.\r\n4. Thời hạn cấm huy động vốn là từ 01 năm đến 03 năm, kể từ ngày bản án có hiệu lực pháp luật.', 'law_81', '2024-05-02 23:55:55', '2024-05-03 00:01:59'),
(82, 'Điều 82. Các biện pháp tư pháp áp dụng đối với pháp nhân thương mại phạm tội\r\n1. Tòa án có thể quyết định áp dụng các biện tư pháp sau đây đối với pháp nhân thương mại phạm tội:\r\na) Các biện pháp tư pháp quy định tại Điều 47 và Điều 48 của Bộ luật này;\r\nb) Buộc khôi phục lại tình trạng ban đầu;\r\nc) Buộc thực hiện một số biện pháp nhằm khắc phục, ngăn chặn hậu quả tiếp tục xảy ra.\r\n2. Tòa án có thể quyết định áp dụng biện pháp tư pháp buộc pháp nhân thương mại phạm tội phải khôi phục lại tình trạng ban đầu đã bị thay đổi do hành vi phạm phạm tội của mình gây ra.\r\n3. Căn cứ vào từng trường hợp phạm tội cụ thể, Tòa án có thể quyết định buộc pháp nhân thương mại phạm tội phải thực hiện một hoặc một số biện pháp sau đây nhằm khắc phục, ngăn chặn hậu quả của tội phạm:\r\na) Buộc tháo dỡ công trình, phần công trình xây dựng không có giấy phép hoặc xây dựng không đúng với giấy phép;\r\nb) Buộc khắc phục tình trạng ô nhiễm môi trường, lây lan dịch bệnh;\r\nc) Buộc đưa ra khỏi lãnh thổ nước Cộng hòa xã hội chủ nghĩa Việt Nam hoặc tái xuất hàng hóa, vật phẩm, phương tiện được đưa vào lãnh thổ nước Cộng hòa xã hội chủ nghĩa Việt Nam, nhập khẩu trái với quy định của pháp luật hoặc được tạm nhập, tái xuất nhưng không tái xuất theo đúng quy định của pháp luật; hàng hóa nhập khẩu, quá cảnh xâm phạm quyền sở hữu trí tuệ, hàng hóa giả mạo quyền sở hữu trí tuệ, phương tiện, nguyên liệu, vật liệu nhập khẩu được sử dụng chủ yếu để sản xuất, kinh doanh hàng hóa giả mạo về sở hữu trí tuệ sau khi đã loại bỏ yếu tố vi phạm;\r\nd) Buộc tiêu hủy hàng hóa, vật phẩm gây hại cho sức khỏe con người, vật nuôi, cây trồng và môi trường, văn hóa phẩm có nội dung độc hại hoặc tang vật khác thuộc đối tượng bị tiêu hủy theo quy định của pháp luật;\r\nđ) Buộc loại bỏ yếu tố vi phạm trên hàng hóa, bao bì hàng hóa, phương tiện kinh doanh, vật phẩm;\r\ne) Buộc thu hồi sản phẩm, hàng hóa vi phạm đang lưu thông trên thị trường.', 'law_82', '2024-05-02 23:55:55', '2024-05-03 00:02:02'),
(83, 'Điều 83. Căn cứ quyết định hình phạt đối với pháp nhân thương mại phạm tội\r\nKhi quyết định hình phạt, Tòa án căn cứ vào quy định của Bộ luật này, cân nhắc tính chất và mức độ nguy hiểm cho xã hội của hành vi phạm tội, việc chấp hành pháp luật của pháp nhân thương mại và các tình tiết giảm nhẹ và tăng nặng trách nhiệm hình sự áp dụng đối với pháp nhân thương mại.', 'law_83', '2024-05-02 23:55:55', '2024-05-03 00:02:06'),
(84, 'Điều 84. Các tình tiết giảm nhẹ trách nhiệm hình sự áp dụng đối với pháp nhân thương mại\r\n1. Các tình tiết sau đây là tình tiết giảm nhẹ trách nhiệm hình sự:\r\na) Đã ngăn chặn hoặc làm giảm bớt tác hại của tội phạm;\r\nb) Tự nguyện sửa chữa, bồi thường thiệt hại hoặc khắc phục hậu quả;\r\nc) Phạm tội nhưng chưa gây thiệt hại hoặc gây thiệt hại không lớn;\r\nd) Tích cực hợp tác với cơ quan có trách nhiệm trong việc phát hiện tội phạm hoặc trong quá trình giải quyết vụ án;\r\nđ) Có nhiều đóng góp trong việc thực hiện chính sách xã hội.\r\n2. Khi quyết định hình phạt, Tòa án có thể coi các tình tiết khác là tình tiết giảm nhẹ, nhưng phải ghi rõ lý do giảm nhẹ trong bản án.\r\n3. Các tình tiết giảm nhẹ đã được Bộ luật này quy định là dấu hiệu định tội hoặc định khung thì không được coi là tình tiết giảm nhẹ trong khi quyết định hình phạt.', 'law_84', '2024-05-02 23:55:55', '2024-05-03 00:02:09'),
(85, 'Điều 85. Các tình tiết tăng nặng trách nhiệm hình sự áp dụng đối với pháp nhân thương mại\r\n1. Chỉ các tình tiết sau đây mới là tình tiết tăng nặng trách nhiệm hình sự:\r\na) Câu kết với pháp nhân thương mại khác để phạm tội;\r\nb) Cố ý thực hiện tội phạm đến cùng;\r\nc) Phạm tội 02 lần trở lên;\r\nd) Tái phạm hoặc tái phạm nguy hiểm;\r\nđ) Lợi dụng hoàn cảnh chiến tranh, tình trạng khẩn cấp, thiên tai, dịch bệnh hoặc những khó khăn đặc biệt khác của xã hội để phạm tội;\r\ne) Dùng thủ đoạn tinh vi để phạm tội hoặc nhằm trốn tránh, che giấu tội phạm.\r\n2. Các tình tiết đã được Bộ luật này quy định là dấu hiệu định tội hoặc định khung hình phạt thì không được coi là tình tiết tăng nặng.', 'law_85', '2024-05-02 23:55:55', '2024-05-03 00:02:12'),
(86, 'Điều 86. Quyết định hình phạt trong trường hợp pháp nhân thương mại phạm nhiều tội\r\nKhi xét xử cùng 01 lần pháp nhân thương mại phạm nhiều tội, Tòa án quyết định hình phạt đối với từng tội và tổng hợp hình phạt theo quy định sau đây:\r\n1. Đối với hình phạt chính:\r\na) Nếu các hình phạt đã tuyên cùng là phạt tiền thì các khoản tiền phạt được cộng lại thành hình phạt chung. Hình phạt tiền không tổng hợp với các hình phạt khác;\r\nb) Nếu các hình phạt đã tuyên là đình chỉ hoạt động có thời hạn và đình chỉ hoạt động vĩnh viễn trong cùng lĩnh vực hoặc hình phạt đã tuyên cùng là đình chỉ hoạt động vĩnh viễn trong cùng lĩnh vực thì hình phạt chung là đình chỉ hoạt động vĩnh viễn trong lĩnh vực đó;\r\nc) Nếu các hình phạt đã tuyên là đình chỉ hoạt động có thời hạn trong cùng lĩnh vực thì được tổng hợp thành hình phạt chung nhưng không vượt quá 04 năm;\r\nd) Nếu trong số các hình phạt đã tuyên có hình phạt đình chỉ hoạt động vĩnh viễn thuộc trường hợp quy định tại khoản 2 Điều 79 của Bộ luật này thì hình phạt chung là đình chỉ hoạt động vĩnh viễn đối với toàn bộ hoạt động;\r\nđ) Nếu các hình phạt đã tuyên là đình chỉ hoạt động có thời hạn trong các lĩnh vực khác nhau hoặc đình chỉ hoạt động vĩnh viễn trong các lĩnh vực khác nhau hoặc đình chỉ hoạt động có thời hạn và đình chỉ hoạt động vĩnh viễn trong các lĩnh vực khác nhau thì không tổng hợp.\r\n2. Đối với hình phạt bổ sung:\r\na) Nếu các hình phạt đã tuyên là cùng loại thì hình phạt chung được quyết định trong giới hạn do Bộ luật này quy định đối với hình phạt đó; riêng đối với hình phạt tiền thì các khoản tiền được cộng lại thành hình phạt chung;\r\nb) Nếu các hình phạt đã tuyên là khác loại thì pháp nhân thương mại bị kết án phải chấp hành tất cả các hình phạt đã tuyên.', 'law_86', '2024-05-02 23:55:55', '2024-05-03 00:02:16'),
(87, 'Điều 87. Tổng hợp hình phạt của nhiều bản án\r\n1. Trường hợp pháp nhân thương mại đang chấp hành một bản án mà lại bị xét xử về tội đã phạm trước khi có bản án này, thì Tòa án quyết định hình phạt đối với tội đang bị xét xử, sau đó quyết định hình phạt chung theo quy định tại Điều 86 của Bộ luật này.\r\nThời gian đã chấp hành hình phạt của bản án trước về đình chỉ hoạt động có thời hạn, cấm kinh doanh, cấm hoạt động trong một số lĩnh vực nhất định hoặc cấm huy động vốn được trừ vào thời hạn chấp hành hình phạt chung.\r\n2. Khi xét xử một pháp nhân thương mại đang phải chấp hành một bản án mà lại thực hiện hành vi phạm tội mới, Tòa án quyết định hình phạt đối với tội mới, sau đó tổng hợp với phần hình phạt chưa chấp hành của bản án trước rồi quyết định hình phạt chung theo quy định tại Điều 86 của Bộ luật này.\r\n3. Trong trường hợp một pháp nhân thương mại phải chấp hành nhiều bản án đã có hiệu lực pháp luật mà các hình phạt của các bản án chưa được tổng hợp, thì Chánh án Tòa án có thẩm quyền ra quyết định tổng hợp hình phạt của các bản án theo quy định tại khoản 1 và khoản 2 Điều này.', 'law_87', '2024-05-02 23:55:55', '2024-05-03 00:02:19'),
(88, 'Điều 88. Miễn hình phạt\r\nPháp nhân thương mại phạm tội có thể được miễn hình phạt khi đã khắc phục toàn bộ hậu quả và đã bồi thường toàn bộ thiệt hại do hành vi phạm tội gây ra.', 'law_88', '2024-05-02 23:55:55', '2024-05-03 00:02:23'),
(89, 'Điều 89. Xóa án tích\r\nPháp nhân thương mại bị kết án đương nhiên được xóa án tích nếu trong thời hạn 02 năm kể từ khi chấp hành xong hình phạt chính, hình phạt bổ sung, các quyết định khác của bản án hoặc từ khi hết thời hiệu thi hành bản án mà pháp nhân thương mại không thực hiện hành vi phạm tội mới.', 'law_89', '2024-05-02 23:55:55', '2024-05-03 00:02:56'),
(90, 'Điều 90. Áp dụng Bộ luật hình sự đối với người dưới 18 tuổi phạm tội\r\nNgười từ đủ 14 tuổi đến dưới 18 tuổi phạm tội phải chịu trách nhiệm hình sự theo những quy định của Chương này; theo quy định khác của Phần thứ nhất của Bộ luật này không trái với quy định của Chương này.', 'law_90', '2024-05-02 23:55:55', '2024-05-03 00:03:00'),
(91, 'Điều 91. Nguyên tắc xử lý đối với người dưới 18 tuổi phạm tội\r\n1. Việc xử lý người dưới 18 tuổi phạm tội phải bảo đảm lợi ích tốt nhất của người dưới 18 tuổi và chủ yếu nhằm mục đích giáo dục, giúp đỡ họ sửa chữa sai lầm, phát triển lành mạnh, trở thành công dân có ích cho xã hội.\r\nViệc xử lý người dưới 18 tuổi phạm tội phải căn cứ vào độ tuổi, khả năng nhận thức của họ về tính chất nguy hiểm cho xã hội của hành vi phạm tội, nguyên nhân và điều kiện gây ra tội phạm.\r\n2. Người dưới 18 tuổi phạm tội thuộc một trong các trường hợp sau đây và có nhiều tình tiết giảm nhẹ, tự nguyện khắc phục phần lớn hậu quả, nếu không thuộc trường hợp quy định tại Điều 29 của Bộ luật này, thì có thể được miễn trách nhiệm hình sự và áp dụng một trong các biện pháp quy định tại Mục 2 Chương này:\r\na) Người từ đủ 16 tuổi đến dưới 18 tuổi phạm tội ít nghiêm trọng, phạm tội nghiêm trọng, trừ tội phạm quy định tại các điều 134, 141, 171, 248, 249, 250, 251 và 252 của Bộ luật này;\r\nb) Người từ đủ 14 tuổi đến dưới 16 tuổi phạm tội rất nghiêm trọng quy định tại khoản 2 Điều 12 của Bộ luật này, trừ tội phạm quy định tại các điều 123, 134, 141, 142, 144, 150, 151, 168, 171, 248, 249, 250, 251 và 252 của Bộ luật này;\r\nc) Người dưới 18 tuổi là người đồng phạm có vai trò không đáng kể trong vụ án.\r\n3. Việc truy cứu trách nhiệm hình sự người dưới 18 tuổi phạm tội chỉ trong trường hợp cần thiết và phải căn cứ vào những đặc điểm về nhân thân của họ, tính chất nguy hiểm cho xã hội của hành vi phạm tội và yêu cầu của việc phòng ngừa tội phạm.\r\n4. Khi xét xử, Tòa án chỉ áp dụng hình phạt đối với người dưới 18 tuổi phạm tội nếu xét thấy việc miễn trách nhiệm hình sự và áp dụng một trong các biện pháp quy định tại Mục 2 hoặc việc áp dụng biện pháp giáo dục tại trường giáo dưỡng quy định tại Mục 3 Chương này không bảo đảm hiệu quả giáo dục, phòng ngừa.\r\n5. Không xử phạt tù chung thân hoặc tử hình đối với người dưới 18 tuổi phạm tội.\r\n6. Tòa án chỉ áp dụng hình phạt tù có thời hạn đối với người dưới 18 tuổi phạm tội khi xét thấy các hình phạt và biện pháp giáo dục khác không có tác dụng răn đe, phòng ngừa.\r\nKhi xử phạt tù có thời hạn, Tòa án cho người dưới 18 tuổi phạm tội được hưởng mức án nhẹ hơn mức án áp dụng đối với người đủ 18 tuổi trở lên phạm tội tương ứng và với thời hạn thích hợp ngắn nhất.\r\nKhông áp dụng hình phạt bổ sung đối với người dưới 18 tuổi phạm tội.\r\n7. Án đã tuyên đối với người chưa đủ 16 tuổi phạm tội, thì không tính để xác định tái phạm hoặc tái phạm nguy hiểm.', 'law_91', '2024-05-02 23:55:55', '2024-05-03 00:03:07'),
(92, 'Điều 92. Điều kiện áp dụng\r\nCơ quan điều tra, Viện kiểm sát hoặc Tòa án chỉ quyết định miễn trách nhiệm hình sự và áp dụng biện pháp khiển trách, hòa giải tại cộng đồng hoặc biện pháp giáo dục tại xã, phường, thị trấn, nếu người dưới 18 tuổi phạm tội hoặc người đại diện hợp pháp của họ đồng ý với việc áp dụng một trong các biện pháp này.', 'law_92', '2024-05-02 23:55:55', '2024-05-03 00:03:11'),
(93, 'Điều 93. Khiển trách\r\n1. Khiển trách được áp dụng đối với người dưới 18 tuổi phạm tội thuộc một trong các trường hợp sau đây nhằm giúp họ nhận thức rõ hành vi phạm tội, hậu quả gây ra đối với cộng đồng, xã hội và nghĩa vụ của họ:\r\na) Người từ đủ 16 tuổi đến dưới 18 tuổi lần đầu phạm tội ít nghiêm trọng thuộc trường hợp quy định tại điểm a khoản 2 Điều 91 của Bộ luật này;\r\nb) Người dưới 18 tuổi là người đồng phạm có vai trò không đáng kể trong vụ án.\r\n2. Cơ quan điều tra, Viện kiểm sát hoặc Tòa án quyết định áp dụng biện pháp khiển trách. Việc khiển trách đối với người dưới 18 tuổi phạm tội phải có sự chứng kiến của cha mẹ hoặc người đại diện hợp pháp của người dưới 18 tuổi.\r\n3. Người bị khiển trách phải thực hiện các nghĩa vụ sau đây:\r\na) Tuân thủ pháp luật, nội quy, quy chế của nơi cư trú, học tập, làm việc;\r\nb) Trình diện trước cơ quan có thẩm quyền khi được yêu cầu;\r\nc) Tham gia các chương trình học tập, dạy nghề do địa phương tổ chức, tham gia lao động với hình thức phù hợp.\r\n4. Tuỳ từng trường hợp cụ thể cơ quan có thẩm quyền ấn định thời gian thực hiện các nghĩa vụ quy định tại điểm b và điểm c khoản 3 Điều này từ 03 tháng đến 01 năm.', 'law_93', '2024-05-02 23:55:55', '2024-05-03 00:03:14'),
(94, 'Điều 94. Hòa giải tại cộng đồng\r\n1. Hòa giải tại cộng đồng được áp dụng đối với người dưới 18 tuổi phạm tội thuộc một trong các trường hợp sau đây:\r\na) Người từ đủ 16 tuổi đến dưới 18 tuổi phạm tội ít nghiêm trọng hoặc phạm tội nghiêm trọng thuộc trường hợp quy định tại điểm a khoản 2 Điều 91 của Bộ luật này;\r\nb) Người từ đủ 14 tuổi đến dưới 16 tuổi phạm tội rất nghiêm trọng thuộc trường hợp quy định tại điểm b khoản 2 Điều 91 của Bộ luật này.\r\n2. Cơ quan điều tra, Viện kiểm sát hoặc Tòa án phối hợp với Ủy ban nhân dân cấp xã tổ chức việc hòa giải tại cộng đồng khi người bị hại hoặc người đại diện hợp pháp của người bị hại đã tự nguyện hòa giải và đề nghị miễn trách nhiệm hình sự.\r\n3. Người được áp dụng biện pháp hòa giải tại cộng đồng phải thực hiện các nghĩa vụ sau đây:\r\na) Xin lỗi người bị hại và bồi thường thiệt hại;\r\nb) Nghĩa vụ quy định tại khoản 3 Điều 93 của Bộ luật này.\r\n4. Tùy từng trường hợp cụ thể, cơ quan có thẩm quyền ấn định thời điểm xin lỗi, thời gian thực hiện nghĩa vụ bồi thường thiệt hại quy định tại điểm a khoản 3 Điều này và nghĩa vụ quy định tại điểm b và điểm c khoản 3 Điều 93 của Bộ luật này từ 03 tháng đến 01 năm.', 'law_94', '2024-05-02 23:55:55', '2024-05-03 00:03:18'),
(95, 'Điều 95. Giáo dục tại xã, phường, thị trấn\r\n1. Cơ quan điều tra, Viện kiểm sát hoặc Tòa án có thể áp dụng biện pháp giáo dục tại xã, phường, thị trấn từ 01 năm đến 02 năm đối với người dưới 18 tuổi phạm tội thuộc một trong các trường hợp sau đây:\r\na) Người từ đủ 16 tuổi đến dưới 18 tuổi phạm tội ít nghiêm trọng hoặc phạm tội nghiêm trọng thuộc trường hợp quy định tại điểm a khoản 2 Điều 91 của Bộ luật này;\r\nb) Người từ đủ 14 tuổi đến dưới 16 tuổi phạm tội rất nghiêm trọng thuộc trường hợp quy định tại điểm b khoản 2 Điều 91 của Bộ luật này.\r\n2. Người được Cơ quan điều tra, Viện kiểm sát hoặc Tòa án giao cho Ủy ban nhân dân cấp xã tổ chức giám sát, giáo dục phải thực hiện các nghĩa vụ sau đây:\r\na) Chấp hành đầy đủ nghĩa vụ về học tập, lao động;\r\nb) Chịu sự giám sát, giáo dục của gia đình, xã, phường, thị trấn;\r\nc) Không đi khỏi nơi cư trú khi không được phép;\r\nd) Các nghĩa vụ theo quy định tại khoản 3 Điều 93 của Bộ luật này.\r\n3. Nếu người được giáo dục tại xã, phường, thị trấn đã chấp hành một phần hai thời hạn và có nhiều tiến bộ thì theo đề nghị của Ủy ban nhân dân cấp xã được giao trách nhiệm giám sát, giáo dục, cơ quan đã áp dụng biện pháp này có thể quyết định chấm dứt thời hạn giáo dục tại xã, phường, thị trấn.', 'law_95', '2024-05-02 23:55:55', '2024-05-03 00:03:22'),
(96, 'Điều 96. Giáo dục tại trường giáo dưỡng\r\n1. Tòa án có thể áp dụng biện pháp giáo dục tại trường giáo dưỡng từ 01 năm đến 02 năm đối với người dưới 18 tuổi phạm tội, nếu thấy do tính chất nghiêm trọng của hành vi phạm tội, do nhân thân và môi trường sống của người đó mà cần đưa người đó vào một tổ chức giáo dục có kỷ luật chặt chẽ.\r\n2. Người được giáo dục tại trường giáo dưỡng phải chấp hành đầy đủ những nghĩa vụ về học tập, học nghề, lao động, sinh hoạt dưới sự quản lý, giáo dục của nhà trường.', 'law_96', '2024-05-03 00:04:10', '2024-05-03 00:04:10'),
(97, 'Điều 97. Chấm dứt trước thời hạn biện pháp giáo dục tại trường giáo dưỡng\r\nNếu người được giáo dục tại trường giáo dưỡng đã chấp hành một phần hai thời hạn, có nhiều tiến bộ, thì theo đề nghị của trường giáo dưỡng được giao trách nhiệm quản lý, giáo dục, Tòa án có thể quyết định chấm dứt thời hạn giáo dục tại trường giáo dưỡng.', 'law_97', '2024-05-03 00:04:10', '2024-05-03 00:04:10'),
(98, 'Điều 98. Các hình phạt được áp dụng đối với người dưới 18 tuổi phạm tội\r\nNgười dưới 18 tuổi phạm tội chỉ bị áp dụng một trong các hình phạt sau đây đối với mỗi tội phạm:\r\n1. Cảnh cáo;\r\n2. Phạt tiền;\r\n3. Cải tạo không giam giữ;\r\n4. Tù có thời hạn.', 'law_98', '2024-05-03 00:05:27', '2024-05-03 00:05:27'),
(99, 'Điều 99. Phạt tiền\r\nPhạt tiền được áp dụng là hình phạt chính đối với người từ đủ 16 tuổi đến dưới 18 tuổi, nếu người đó có thu nhập hoặc có tài sản riêng.\r\nMức tiền phạt đối với người từ đủ 16 tuổi đến dưới 18 tuổi phạm tội không quá một phần hai mức tiền phạt mà điều luật quy định.', 'law_99', '2024-05-03 00:05:27', '2024-05-03 00:05:27'),
(100, 'Điều 100. Cải tạo không giam giữ\r\n1. Hình phạt cải tạo không giam giữ được áp dụng đối với người từ đủ 16 tuổi đến dưới 18 tuổi phạm tội rất nghiêm trọng do vô ý hoặc phạm tội ít nghiêm trọng, phạm tội nghiêm trọng hoặc người từ đủ 14 tuổi đến dưới 16 tuổi phạm tội rất nghiêm trọng.\r\n2. Khi áp dụng hình phạt cải tạo không giam giữ đối với người dưới 18 tuổi phạm tội, thì không khấu trừ thu nhập của người đó.\r\nThời hạn cải tạo không giam giữ đối với người dưới 18 tuổi phạm tội không quá một phần hai thời hạn mà điều luật quy định.', 'law_100', '2024-05-03 00:05:27', '2024-05-03 00:05:27');
